Code: using System;
using System.Collections.Generic;
using System.Linq;
using UglyToad.PdfPig;
using UglyToad.PdfPig.DocumentLayoutAnalysis;
using UglyToad.PdfPig.DocumentLayoutAnalysis.WordExtractor;
using UglyToad.PdfPig.Geometry;

public class PdfLayoutAnalyzer
{
    private readonly string _pdfPath = @"C:\Users\Kris\test.pdf";

    public List<TextBlock> AnalyzeDocumentLayout()
    {
        List<TextBlock> orderedTextBlocks = new List<TextBlock>();

        using (PdfDocument pdf = PdfDocument.Open(_pdfPath))
        {
            int pageNumber = 1;
            foreach (Page page in pdf.Pages)
            {
                var wordExtractor = new TextExtractor(page);
                var contentArea = page.GetContentArea();
                var words = wordExtractor.ExtractWords();
                var wordGroups = WordExtractor.GroupWordsByReadingOrder(words, contentArea);

                var textBlocks = wordGroups
                    .Select(group => new TextBlock(group.Select(word => word.Text).ToList(), group.First().BoundingBox))
                    .ToList();

                orderedTextBlocks.AddRange(textBlocks);
            }
        }

        return orderedTextBlocks;
    }
}

public class TextBlock
{
    public TextBlock(List<string> lines, Rectangle boundingBox)
    {
        Lines = lines;
        BoundingBox = boundingBox;
    }

    public List<string> Lines { get; set; }
    public Rectangle BoundingBox { get; set; }
}
