    public class PdfDocumentBuilderExample
    {
        private const string _outputPdfFilePath = @"C:\Users\Kris\new_test.pdf";

        public void CreatePdfDocumentWithText()
        {
            // Create the PDF document with one page
            using (var document = PdfDocument.Create())
            {
                document.AddPage();

                // Register a Standard 14 font
                var fontProvider = new DefaultFontProvider();
                var font = fontProvider.GetFont(StandardFont.TimesRoman, 12);

                // Write multiple lines of text at different positions
