                document.Content.DrawText("First line of text", new Position(100, 750));
                document.Content.DrawText("Second line of text", new Position(100, 700));
                document.Content.DrawText("Third line of text", new Position(100, 650));

                // Save the generated PDF document
                document.Save(_outputPdfFilePath);
            }

            Console.WriteLine($"New PDF document created at {_outputPdfFilePath}.");
        }
    }
}
