Code: using System;
using System.Collections.Generic;
using UglyToad.PdfPig.DocumentModel;
using UglyToad.PdfPig.Generator;

namespace PdfPigExample
{
    public class PdfShapeDrawer
    {
        private readonly PdfPage _pdfPage;
        private readonly PdfPageContent _pdfPageContent;

        public PdfShapeDrawer(PdfPage pdfPage)
        {
            _pdfPage = pdfPage;
            _pdfPageContent = pdfPage.CreateContent();
        }

        public void DrawLine(Position start, Position end, PdfColors color, double lineWidth = 1)
        {
            using (var line = _pdfPageContent.DrawLine())
            {
                line.MoveTo(start);
                line.LineTo(end);
                line.SetStrokeColor(color);
                line.SetLineWidth(lineWidth);
                line.Stroke();
            }
        }

        public void DrawRectangle(Rectangle rectangle, PdfColors fillColor, PdfColors strokeColor, double lineWidth = 1)
        {
            using (var rectangleShape = _pdfPageContent.DrawRectangle(rectangle))
            {
                rectangleShape.SetFillColor(fillColor);
                rectangleShape.SetStrokeColor(strokeColor);
                rectangleShape.SetLineWidth(lineWidth);
                rectangleShape.FillStroke();
            }
        }
    }
}
