```csharp
using PdfMerger;
using System;
using System.IO;
using System.Linq;

public class PdfMergerClass
{
    public byte[] MergePdfFiles(params string[] filePaths)
    {
        using (var merger = new PdfMerger())
        {
            foreach (var filePath in filePaths)
            {
                merger.Add(filePath);
            }

            using (var ms = new MemoryStream())
            {
                merger.Merge(ms);
                return ms.ToArray();
            }
        }
    }
}
```
