        var mergedPdf = merger.MergePdfFiles(pdfPath, @"C:\Users\Kris\test_with_text.pdf", @"C:\Users\Kris\test_with_shapes.pdf");
        File.WriteAllBytes(@"C:\Users\Kris\merged.pdf", mergedPdf);

        Console.WriteLine("Done!");
    }
}
