            var textBlocks = pageWordExtractor.GetTextBlocks();

            // Get the reading order for the page
            var readingOrder = pageWordExtractor.GetReadingOrder();

            // Produce ordered text blocks
            var orderedBlocks = new List<string>();
            foreach (var block in readingOrder)
            {
