```csharp
using System;
using System.Collections.Generic;
using System.IO;
using UglyToad.PdfPig;

public class PdfImageAndHyperlinkExtractor
{
    public List<byte[]> GetImagesFromPage(string filePath, int pageNumber)
    {
        var images = new List<byte[]>();

        // Open the PDF document
        using (var pdf = PdfDocument.Open(filePath))
        {
            // Get the specified page
            var page = pdf.GetPage(pageNumber);

            // Extract images
            foreach (var image in page.GetImages())
            {
                using (var stream = new MemoryStream())
                {
                    image.SaveAsBytes().CopyTo(stream);
                    images.Add(stream.ToArray());
                }
            }
        }

        return images;
    }

    public List<Uri> GetHyperlinksFromPage(string filePath, int pageNumber)
    {
        var hyperlinks = new List<Uri>();

        // Open the PDF document
        using (var pdf = PdfDocument.Open(filePath))
        {
            // Get the specified page
            var page = pdf.GetPage(pageNumber);

            // Extract hyperlinks
            foreach (var annotation in page.Annotations)
            {
                var uriAnnotation = annotation as UriAnnotation;
                if (uriAnnotation != null && uriAnnotation.Uri != null)
                {
                    hyperlinks.Add(uriAnnotation.Uri);
                }
            }
        }

        return hyperlinks;
    }
}
```

