```csharp
using System;
using System.IO;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Core;
using UglyToad.PdfPig.Writer;

public class PdfDocumentCreator
{
    private readonly string _outputPath;

    public PdfDocumentCreator(string outputPath)
    {
        _outputPath = outputPath;
    }

    public void CreatePdfDocument()
    {
        var builder = new PdfDocumentBuilder();

        // Create a new page
        var page = builder.AddPage(PaperSize.A4);

        // Register a Standard 14 font
        var font = builder.AddStandard14Font(Standard14Font.Helvetica);

        // Add multiple lines of text at different positions
        page.AddText("This is a line of text.", 100, 700, font, 12, TextRenderMode.FillText);
        page.AddText("This is another line of text.", 100, 650, font, 12, TextRenderMode.FillText);

        // Save the document
        var document = builder.Build();
        document.Save(_outputPath);

        Console.WriteLine($"PDF document created at {_outputPath}");
    }
}

public class Program
{
    public static void Main()
