```csharp
using System;
using System.Collections.Generic;
using System.IO;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;
using UglyToad.PdfPig.Graphics.Colors;

public class PdfExtractor
{
    private readonly string _pdfPath;

    public PdfExtractor(string pdfPath)
    {
        _pdfPath = pdfPath;
    }

    public IEnumerable<Image> GetImagesFromPage(int pageNumber)
    {
        using (var pdfDocument = PdfDocument.Open(_pdfPath))
        {
            var page = pdfDocument.GetPage(pageNumber);
            return page.GetImages();
        }
    }

    public IEnumerable<(int PageNumber, string Uri)> GetHyperlinksFromPage(int pageNumber)
    {
        using (var pdfDocument = PdfDocument.Open(_pdfPath))
        {
            var page = pdfDocument.GetPage(pageNumber);
            var links = new List<(int PageNumber, string Uri)>();

            foreach (var annotation in page.ExperimentalAccess.GetAnnotations())
            {
                if (annotation.Type == AnnotationType.Link)
                {
                    var link = (PdfLinkAnnotation)annotation;
                    var uri = link.GetUri();
                    links.Add((pageNumber, uri));
                }
            }

            return links;
        }
    }
}

public class Program
{
    public static void Main()
    {
        var extractor = new PdfExtractor("C:\\Users\\Kris\\test.pdf");

        var images = extractor.GetImagesFromPage(1);
        foreach (var image in images)
        {
            Console.WriteLine($"Image: {image.Width}x{image.Height}, ColorSpace: {image.ColorSpace}");
        }

        var links = extractor.GetHyperlinksFromPage(1);
        foreach (var link in links)
        {
            Console.WriteLine($"Page: {link.PageNumber}, URI: {link.Uri}");
        }
    }
}
```

