using System;
using System.Collections.Generic;
using System.IO;
using iTextSharp.text;
using iTextSharp.text.pdf;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;

public class PdfPigDemo
{
    public static void Main()
    {
        // Read metadata
        using (var pdf = PdfDocument.Open(@"C:\Users\Kris\test.pdf"))
        {
            var info = pdf.Information;
            Console.WriteLine($"Title: {info.Title}");
            Console.WriteLine($"Author: {info.Author}");
            Console.WriteLine($"Pages: {pdf.NumberOfPages}");
        }

        // Extract text and words
        using (var pdf = PdfDocument.Open(@"C:\Users\Kris\test.pdf"))
        {
            foreach (var page in pdf.GetPages())
            {
                Console.WriteLine(page.Text);
                foreach (var word in page.GetWords())
                {
                    Console.WriteLine(word.Text);
                }
            }
        }

        // Analyze layout
        using (var pdf = PdfDocument.Open(@"C:\Users\Kris\test.pdf"))
        {
            foreach (var page in pdf.GetPages())
            {
                foreach (var block in page.GetTextBlocks())
                {
                    Console.WriteLine(block.Text);
                    Console.WriteLine($"Position: {block.BoundingBox.TopLeft}, Size: {block.BoundingBox.Size}");
                }
            }
        }

        // Create a new PDF with text and shapes
        using (var outputStream = new MemoryStream())
        {
            using (var document = new Document())
            {
                using (var writer = PdfWriter.GetInstance(document, outputStream))
                {
                    document.Open();

                    var paragraph = new Paragraph("Hello, world!");
                    var chunk = new Chunk("Hello, world!");
                    var shape = new Rectangle(50, 50);

                    document.Add(paragraph);
                    document.Add(chunk);
                    writer.DirectContent.AddTemplate(shape, 100, 100);

                    document.Close();
                }
            }

            File.WriteAllBytes("C:\\Users\\Kris\\new.pdf", outputStream.ToArray());
        }

        // Merge PDFs
        var merger = new PdfMerger();
        var filePaths = new List<string>
        {
            "C:\\Users\\Kris\\test.pdf",
            "C:\\Users\\Kris\\another.pdf",
            "C:\\Users\\Kris\\one_more.pdf"
        };
        var mergedPdf = merger.MergePdfFiles(filePaths.ToArray());
        File.WriteAllBytes("C:\\Users\\Kris\\merged.pdf", mergedPdf);
    }
}
