Code: using System;
using System.Collections.Generic;
using System.IO;
using UglyToad.PdfPig;
using UglyToad.PdfPig.DocumentLayoutAnalysis;

public class PdfLayoutAnalyzer
{
    public List<string> AnalyzeDocumentLayout(string filePath, int pageNumber)
    {
        // Open the PDF document
        using (var pdf = PdfDocument.Open(filePath))
        {
            // Get the specified page
            var page = pdf.GetPage(pageNumber);

            // Extract words using NearestNeighbourWordExtractor
            var wordExtractor = NearestNeighbourWordExtractor.Instance;
            var words = wordExtractor.GetWords(page);

            // Create a new PageWordExtractor
            var pageWordExtractor = new PageWordExtractor(words);

            // Get the text blocks for the page
            var textBlocks = pageWordExtractor.GetTextBlocks();

            // Get the reading order for the page
            var readingOrder = pageWordExtractor.GetReadingOrder();

            // Produce ordered text blocks
            var orderedBlocks = new List<string>();
            foreach (var block in readingOrder)
            {
                var textBlock = textBlocks[block];
                orderedBlocks.Add(textBlock.Text);
            }

            return orderedBlocks;
        }
    }
}
