Code: using System;
using System.IO;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Writer;

public class PdfCreator
{
    public void CreateDocument(string filePath)
    {
        // Create a new PDF document
        using (var pdf = new PdfDocumentBuilder())
        {
            // Add a new page
            var page = pdf.AddPage(PdfPageSize.A4);

            // Register a Standard 14 font
            var font = pdf.AddStandard14Font(Standard14Font.Helvetica);

            // Write text at different positions
            var text = new PdfTextBuilder(pdf)
                .SetFont(font)
                .SetFontSize(12)
                .AddText("Hello, world!\n", 100, 700)
                .AddText("This is an example of text.\n", 50, 650)
                .AddText("This text is on a new line.\n", 50, 600)
                .Build();

            page.Add(text);

            // Save the PDF document
            pdf.Write(filePath);
        }
    }
}
