Code: using System;
using System.IO;
using System.Linq;
using UglyToad.PdfPig.Writer;

public class PdfMerger
{
    public byte[] MergePdfFiles(params string[] filePaths)
    {
        // Create a new PDF document
        using (var pdf = new PdfDocumentBuilder())
        {
            // Merge all PDF documents
            foreach (var filePath in filePaths)
            {
                using (var pdfToMerge = PdfDocument.Open(filePath))
                {
                    foreach (var page in pdfToMerge.Pages)
                    {
                        pdf.AddPage(page);
                    }
                }
            }

            // Save the merged PDF document to a byte array
            using (var stream = new MemoryStream())
            {
                pdf.Write(stream);
                return stream.ToArray();
            }
        }
    }
}
