Code: using System;
using System.IO;
using UglyToad.PdfPig.Core;
using UglyToad.PdfPig.Writer;
using UglyToad.PdfPig.Graphics;

public class PdfDocumentCreator
{
    private readonly string _outputPath;

    public PdfDocumentCreator(string outputPath)
    {
        _outputPath = outputPath;
    }

    public void CreatePdfDocument()
    {
        var builder = new PdfDocumentBuilder();

        // Create a new page
        var page = builder.AddPage(PageSize.A4);

        // Set up the page builder
        var pageBuilder = new PdfPageBuilder(page);

        // Draw a line from (100, 700) to (200, 600) with a color and line width
        var line = new PdfLine(new PdfPoint(100, 700), new PdfPoint(200, 600))
        {
            Color = new PdfRgbColor(0, 0, 255), // Blue color
            LineWidth = 2
        };
        pageBuilder.AddLine(line);

        // Draw a rectangle at (150, 650) with size (100, 100) and a color and line width
        var rectangle = new PdfRectangle(new PdfPoint(150, 650), new PdfPoint(150 + 100, 650 + 100))
        {
            Color = new PdfRgbColor(255, 0, 0), // Red color
            LineWidth = 1
        };
        pageBuilder.AddRectangle(rectangle);

        // Save the document
