    private void DrawLine(PdfPageBuilder page, double x1, double y1, double x2, double y2, Color color, double lineWidth)
    {
        var line = new PdfLine(x1, y1, x2, y2);
        line.SetStrokeColor(color);
        line.SetStrokeWidth(lineWidth);
        page.Add(line);
    }

    private void DrawRectangle(PdfPageBuilder page, double x, double y, double width, double height, Color color, double lineWidth)
    {
        var rectangle = new PdfRectangle(x, y, width, height);
