using System;
using System.Collections.Generic;
using System.Linq;
using iText.Kernel.Pdf;
using iText.Kernel.Pdf.Canvas.Parser.Listener;
using iText.Kernel.Pdf.Canvas.Parser;
using iText.Layout;
using iText.Layout.Element;
using UglyToad.PdfPig;

public class Program
{
    public static void Main(string[] args)
    {
        // Read metadata
        var pdfReader = new PdfReader(new RandomAccessFileOrArray("C:\\Users\\Kris\\test.pdf"), null);
        Console.WriteLine($"Title: {pdfReader.Info["Title"]}");
        Console.WriteLine($"Author: {pdfReader.Info["Author"]}");
        Console.WriteLine($"Subject: {pdfReader.Info["Subject"]}");
        Console.WriteLine($"Keywords: {pdfReader.Info["Keywords"]}");
        Console.WriteLine($"Creator: {pdfReader.Info["Creator"]}");

        // Extract text and words
        using (var pdfDocument = PdfDocument.Open("C:\\Users\\Kris\\test.pdf"))
        {
            for (var i = 1; i <= pdfDocument.GetNumberOfPages(); i++)
            {
                var strategy = new SimpleTextExtractionStrategy();
                var pageText = PdfTextExtractor.GetTextFromPage(pdfDocument.GetPage(i), strategy);
                Console.WriteLine($"Page {i} text: {pageText}");
            }
        }

        // Analyze layout
        using (var pdf = PdfDocument.Open("C:\\Users\\Kris\\test.pdf"))
        {
            foreach (var page in pdf.GetPages())
            {
                var textLocations = ContentOrderTextExtractor.GetTextPositions(page);
                foreach (var text in textLocations)
                {
                    Console.WriteLine($"Text: {text.Text}, Position: {text.Position}");
                }
            }
        }

        // Create a new PDF with text and shapes
        var outputPdf = new PdfDocument(new PdfWriter("output.pdf"));
        var document = new Document(outputPdf);
        var paragraph = new Paragraph("Hello, World!").SetFontSize(20);
        document.Add(paragraph);
        var rectangle = new Rectangle(36, 750, 144, 800);
        var rectangleEvent = new iText.Kernel.Pdf.Canvas.Draw.SolidLine(1);
        rectangleEvent.Draw(rectangle, new float[] { 36, 750, 144, 800 }, outputPdf.GetPage(1));
        document.Close();

        // Merge PDFs
        var pdfProcessor = new PdfProcessor();
        var mergedPdf = pdfProcessor.MergePdfFiles(new List<string> { "C:\\Users\\Kris\\test.pdf", "output.pdf" });
        File.WriteAllBytes("merged.pdf", mergedPdf);
    }
}
```

