Code: using UglyToad.PdfPig;
using UglyToad.PdfPig.DocumentLayoutAnalysis;
using UglyToad.PdfPig.DocumentLayoutAnalysis.WordExtractor;
using System.Collections.Generic;
using System.IO;
using System.Threading.Tasks;

public class PdfProcessor
{
    private readonly string filePath;

    public PdfProcessor(string filePath)
    {
        this.filePath = filePath;
    }

    public async Task<Dictionary<int, List<TextBlock>>> AnalyzeDocumentLayout(bool includeImages)
    {
        using (var pdfDocument = PdfDocument.Open(filePath))
        {
            var dla = new DocumentLayoutAnalysis(includeImages);
            var blocksPerPage = new Dictionary<int, List<TextBlock>>();

            for (var pageNumber = 1; pageNumber <= pdfDocument.NumberOfPages; pageNumber++)
            {
                var page = pdfDocument.GetPage(pageNumber);
                var words = dla.GetTextBlocks(page);
                blocksPerPage[pageNumber] = words;
            }

            return blocksPerPage;
        }
    }
}
