public class PdfProcessor
{
    public void CreatePDFDocumentWithShapes()
    {
        using (var pdf = new PdfDocumentBuilder())
        {
            var page = pdf.AddPage(PdfPageSize.A4);

            var blueColor = Color.FromRgb(0, 0, 255);
            var redColor = Color.FromRgb(255, 0, 0);
            var lineWidth = 1.0;

            DrawLine(page, 100, 100, 200, 200, blueColor, lineWidth);
            DrawRectangle(page, 50, 50, 100, 100, redColor, lineWidth);

            var bytes = pdf.Build();
            File.WriteAllBytes("C:\\Users\\Kris\\output.pdf", bytes);
        }
    }

    private void DrawLine(PdfPageBuilder page, double x1, double y1, double x2, double y2, Color color, double lineWidth)
    {
        var line = new PdfLine(x1, y1, x2, y2);
        line.SetStrokeColor(color);
        line.SetStrokeWidth(lineWidth);
        page.Add(line);
    }

    private void DrawRectangle(PdfPageBuilder page, double x, double y, double width, double height, Color color, double lineWidth)
    {
        var rectangle = new PdfRectangle(x, y, width, height);
        rectangle.SetStrokeColor(color);
        rectangle.SetStrokeWidth(lineWidth);
        page.Add(rectangle);
    }
}
