Code: using iText.Kernel.Pdf;
using iText.Kernel.Utils;
using System.Collections.Generic;

public class PdfProcessor
{
    public byte[] MergePdfFiles(List<string> filePaths)
    {
        using (var pdfOutput = new PdfDocument(new PdfWriter("merged.pdf")))
        {
            foreach (string filePath in filePaths)
            {
                using (var pdfSource = new PdfDocument(new PdfReader(filePath)))
                {
                    var pages = PdfDocumentUtil.GetAllPages(pdfSource, pdfOutput);
                    foreach (var page in pages)
                    {
                        pdfOutput.AddPage(page);
                    }
                }
            }

            byte[] bytes = new byte[0];
            using (var ms = new MemoryStream())
            {
                pdfOutput.Close();

                bytes = File.ReadAllBytes("merged.pdf");
                File.Delete("merged.pdf");
            }

            return bytes;
        }
    }
}
