using UglyToad.PdfPig.Core;
using UglyToad.PdfPig.DocumentLayoutAnalysis.WordExtractor;

public class PdfReader
{
    public static async Task<Dictionary<int, List<string>>> GetWordsForPage(string pdfPath)
    {
        using (PdfDocument document = PdfDocument.Open(pdfPath))
        {
            var wordExtractor = new NearestNeighbourWordExtractor();
            Dictionary<int, List<string>> wordsByPage = new Dictionary<int, List<string>>();

            for (int i = 1; i <= document.NumberOfPages; i++)
            {
                Page page = document.GetPage(i);
                IEnumerable<Word> words = wordExtractor.GetWords(page);
                List<string> wordsOnPage = new List<string>();

                foreach (Word word in words)
                {
                    wordsOnPage.Add(word.Text);
                }

                wordsByPage[i] = wordsOnPage;
            }

            return wordsByPage;
        }
    }

    static async Task Main()
    {
        string pdfPath = @"C:\Users\Kris\test.pdf";
        var wordsByPage = await GetWordsForPage(pdfPath);

        foreach (var entry in wordsByPage)
        {
            Console.WriteLine($"Page {entry.Key}: {string.Join(", ", entry.Value)}");
        }
    }
}
```

