```csharp
using UglyToad.PdfPig;
using UglyToad.PdfPig.Writer;

public class PDFShapeDrawer
{
    public void DrawShapes(string outputFilePath)
    {
        // Create a new PDF document builder
        var builder = new PdfDocumentBuilder();

        // Create a new page
        var page = builder.AddPage(PdfPageSize.A4);

        // Create a new page builder
        var pageBuilder = builder.StartPageContentContext(page);

        // Draw a line from (10, 10) to (100, 100) with a line width of 2 and color red
        var line = new PdfLine(new PdfPoint(10, 10), new PdfPoint(100, 100))
        {
            Width = 2,
            Color = PdfColors.Red
        };
        pageBuilder.DrawLine(line);

        // Draw a rectangle from (50, 50) to (150, 150) with a line width of 3 and color blue
        var rectangle = new PdfRectangle(new PdfPoint(50, 50), new PdfPoint(150, 150))
        {
            Width = 3,
            Color = PdfColors.Blue
        };
        pageBuilder.DrawRectangle(rectangle);

        // End the page content context
        builder.EndPageContentContext();

        // Build the document
        var pdf = builder.Build();

        // Save the PDF to a file
        pdf.Save(outputFilePath);
    }
}
```

