```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;
using UglyToad.PdfPig.Core;
using UglyToad.PdfPig.DocumentLayoutAnalysis;
using UglyToad.PdfPig.Writer;

class Program
{
    static void Main(string[] args)
    {
        // Read metadata
        var filePath = @"C:\Users\Kris\test.pdf";
        var pdf = PdfDocument.Open(filePath);
        Console.WriteLine($"Author: {pdf.Information.Author}");
        Console.WriteLine($"Title: {pdf.Information.Title}");

        // Extract text and words
        foreach (var page in pdf.GetPages())
        {
            var text = page.Text;
            Console.WriteLine($"Page {page.Number}: {text}");

            var words = page.GetWords();
            Console.WriteLine($"Page {page.Number} words: {string.Join(", ", words)}");
        }

        // Analyze layout
        using (var document = PdfDocument.Open(filePath))
        {
            var page = document.GetPage(1);
            var letters = page.Letters;
            var words = page.GetWords();
            var sentences = page.GetSentences();
            var lines = page.Lines;

            foreach (var sentence in sentences)
            {
                Console.WriteLine(sentence.Text);
            }
        }

        // Create a new PDF with text and shapes
        var builder = new PdfDocumentBuilder();
        var page = builder.AddPage(PdfPageSize.A4);

        var font = builder.AddStandard14Font(Standard14Font.TimesBold);

        page.AddTextToPage("Hello, World", font, 12, new PdfPoint(10, 50));
        page.AddTextToPage("This is a test", font, 12, new PdfPoint(10, 25));

        var line = new PdfLine(new PdfPoint(10, 10), new PdfPoint(100, 100))
        {
            Width = 2,
            Color = PdfColors.Red
        };
        page.DrawLine(line);

        var rectangle = new PdfRectangle(new PdfPoint(50, 50), new PdfPoint(150, 150))
        {
            Width = 3,
            Color = PdfColors.Blue
        };
        page.DrawRectangle(rectangle);

        var pdfDocument = builder.Build();
        pdfDocument.Save("newDocument.pdf");

        // Merge PDFs
        var merger = new PdfMerger();
        merger.Add(filePath);
        merger.Add(pdfDocument.Save("merged.pdf"));

        var mergedPdf = merger.Merge();
        System.IO.File.WriteAllBytes("merged.pdf", mergedPdf);
    }
}
```

