Code: using System.Collections.Generic;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;

public class PDFLayoutAnalyzer
{
    private string filePath;
    private PdfDocument document;

    public PDFLayoutAnalyzer(string filePath)
    {
        this.filePath = filePath;
    }

    public void OpenDocument()
    {
        document = PdfDocument.Open(filePath);
    }

    public List<TextBlock> GetTextBlocksForPage(int pageNumber)
    {
        if (document == null) return null;

        var page = document.GetPage(pageNumber);
        var textBlocks = new List<TextBlock>();

        var extractor = NearestNeighbourWordExtractor.Instance;
        var words = extractor.GetWords(page);

        foreach (var word in words)
        {
            var block = new TextBlock(word.Text);
            block.AddWord(word);

            // Check if the word is in the same block as the previous word
            if (textBlocks.Count > 0)
            {
                var previousBlock = textBlocks[textBlocks.Count - 1];
                if (word.Location.Y > previousBlock.Location.Y)
                {
                    previousBlock.AddWord(word);
                }
                else
                {
                    textBlocks.Add(block);
                }
            }
            else
            {
                textBlocks.Add(block);
            }
        }

        return textBlocks;
    }
}
