Code: using System.Collections.Generic;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;

public class PDFImageAndHyperlinkExtractor
{
    private string filePath;
    private PdfDocument document;

    public PDFImageAndHyperlinkExtractor(string filePath)
    {
        this.filePath = filePath;
    }

    public void OpenDocument()
    {
        document = PdfDocument.Open(filePath);
    }

    public List<IPdfImage> GetImagesFromPage(int pageNumber)
    {
        if (document == null) return null;

        var page = document.GetPage(pageNumber);

        var images = new List<IPdfImage>();

        foreach (var item in page.GetPageContents())
        {
            if (item is IPdfImage image)
            {
                images.Add(image);
            }
        }

        return images;
    }

    public List<IPdfHyperlink> GetHyperlinksFromPage(int pageNumber)
    {
        if (document == null) return null;

        var page = document.GetPage(pageNumber);

        var hyperlinks = new List<IPdfHyperlink>();

        foreach (var item in page.GetPageContents())
        {
            if (item is IPdfHyperlink link)
            {
                hyperlinks.Add(link);
            }
        }

        return hyperlinks;
    }
}
