public class PdfPigAssistant
{
    public static void ReadDocumentInformation()
    {
        // ...
    }

    public static List&lt;string&gt; ExtractTextByPage(string filePath)
    {
        PdfDocument pdfDocument = PdfDocument.Open(filePath);
