```csharp
using PdfPigDemo;

namespace PdfPigDemoApp
{
    class Program
    {
        static void Main(string[] args)
        {
            var filePath = @"C:\Users\Kris\output.pdf";
            PdfDocumentCreator.CreatePdfDocument(filePath);

            Console.WriteLine($"PDF document created at {filePath}");
            Console.ReadLine();
        }
    }
}
```

