            var totalPages = document.GetNumberOfPages();
            Console.WriteLine("\nDocument Structure:");
            Console.WriteLine($"- Total Pages: {totalPages}");

            for (int i = 1; i <= totalPages; i++)
            {
                var page = document.GetPage(i);
                Console.WriteLine($"- Page {i}");
