using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;
using UglyToad.PdfPig.DocumentLayoutAnalysis.TextExtractor;
using UglyToad.PdfPig.DocumentLayoutAnalysis.WordExtractor;
using UglyToad.PdfPig.DocumentLayoutAnalysis.PageSegmentation;
using UglyToad.PdfPig.DocumentLayoutAnalysis.PageSegmentation.Layouts;
using UglyToad.PdfPig.DocumentLayoutAnalysis.ReadingOrderDetection;
using UglyToad.PdfPig.DocumentLayoutAnalysis.TextBlockOrderDetection;
using UglyToad.PdfPig.Writer;

namespace PdfPigDemo
{
    class AdvancedDocumentLayoutAnalysis
    {
        // TODO: Replace the file path with the actual PDF location.
        var pdf = new PdfDocument("C:\\Users\\Kris\\test.pdf");
        var wordExtractor = new NearestNeighbourWordExtractor();
        var layoutStrategy = new LayoutStrategy();
        var pageSegmentation = new PageSegmentation();
        var readingOrderDetection = new ReadingOrderDetection();
        var textBlockOrderDetection = new TextBlockOrderDetection();

        foreach (var page in pdf.Pages)
        {
            var words = wordExtractor.ExtractWords(page);
            var textBlocks = layoutStrategy.GenerateTextBlocks(words);
            var pageSegments = pageSegmentation.SegmentPage(page);
            var readingOrder = readingOrderDetection.DetectReadingOrder(pageSegments, textBlocks);
            var orderedTextBlocks = textBlockOrderDetection.DetectOrder(readingOrder, textBlocks);
        }
    }
}
