        var wordExtractor = new NearestNeighbourWordExtractor();
        var layoutStrategy = new LayoutStrategy();
        var pageSegmentation = new PageSegmentation();
        var readingOrderDetection = new ReadingOrderDetection();
        var textBlockOrderDetection = new TextBlockOrderDetection();

        foreach (var page in pdf.Pages)
        {
            var words = wordExtractor.ExtractWords(page);
            var textBlocks = layoutStrategy.GenerateTextBlocks(words);
            var pageSegments = pageSegmentation.SegmentPage(page);
            var readingOrder = readingOrderDetection.DetectReadingOrder(pageSegments, textBlocks);
            var orderedTextBlocks = textBlockOrderDetection.DetectOrder(readingOrder, textBlocks);
        }
    }
}
