```csharp
using (var pdf = PdfDocument.Open("C:\\Users\\Kris\\test.pdf"))
{
    var wordExtractor = new NearestNeighbourWordExtractor();
    var pageSegmentation = new PageSegmentation();
    var readingOrderDetector = new ReadingOrderDetector();

    var textBlocks = new Dictionary<PageNumber, List<TextBlock>>();

    for (var page = 1; page <= pdf.GetNumberOfPages(); page++)
    {
        textBlocks.Add(page, new List<TextBlock>());

        var words = wordExtractor.ExtractWords(pdf.GetPage(page));
        var pageSegmentationResult = pageSegmentation.SegmentationResult(pdf.GetPage(page));
        var readingOrderResult = readingOrderDetector.DetectReadingOrder(pageSegmentationResult, words);

        for (var blockNumber = 1; blockNumber <= readingOrderResult.NumberOfBlocks; blockNumber++)
        {
            textBlocks[page].Add(new TextBlock(blockNumber, readingOrderResult.GetText(blockNumber)));
        }
    }

    return textBlocks;
}
```
