    class PdfPigDocument
    {
        public async Task<PdfDocument> ReadDocumentInformation()
        {
            PdfDocument document = await PdfDocument.OpenAsync("C:\\Users\\Kris\\test.pdf");

            int numberOfPages = document.Pages.Count;
            string pdfVersion = document.DocumentInfo.Version;
            string title = document.DocumentInfo.Title;
            string producer = document.DocumentInfo.Producer;

            return document;
        }

        public async Task<PageTextData> ExtractTextByPage()
        {
            PdfDocument document = await ReadDocumentInformation();
            ContentOrderTextExtractor extractor = new ContentOrderTextExtractor(document);
            List<string> extractedText = new List<string>();
            for (int pageNum = 1; pageNum <= document.Pages.Count; pageNum++)
            {
                string text = await extractor.GetTextForPageAsync(pageNum);
                extractedText.Add(text);
            }
            return extractedText;
        }

        public async Task<PageWordData> GetWordsForPage()
        {
            PdfDocument document = await ReadDocumentInformation();
            NearestNeighbourWordExtractor extractor = new NearestNeighbourWordExtractor(document);
            Dictionary<int, List<string>> extractedWords = new Dictionary<int, List<string>>();
            for (int pageNum = 1; pageNum <= document.Pages.Count; pageNum++)
            {
                List<string> words = await extractor.GetWordsForPageAsync(pageNum);
                extractedWords.Add(pageNum, words);
            }
            return extractedWords;
        }

