public class PdfTextExtractor
{
    public List<string> ExtractTextByPage(string pdfPath)
    {
        var extractedText = new List<string>();

        using (var reader = new PdfReader(pdfPath))
        {
            for (var page = 1; page <= reader.NumberOfPages; page++)
            {
                using (var strategy = new iTextSharp.text.pdf.parser.SimpleTextExtractionStrategy())
                {
                    var text = PdfTextExtractor.GetTextFromPage(reader, page, strategy);
                    extractedText.Add(text);
                }
            }
        }

        return extractedText;
    }

    private static string GetTextFromPage(PdfReader reader, int page, iTextSharp.text.pdf.parser.ITextExtractionStrategy strategy)
    {
        return PdfTextExtractor.GetTextFromPage(reader, page, false, strategy);
    }

    private static string GetTextFromPage(PdfReader reader, int page, bool renderImage, iTextSharp.text.pdf.parser.ITextExtractionStrategy strategy)
    {
        return PdfTextExtractor.GetTextFromPage(reader, page, renderImage, strategy, null);
    }

    private static string GetTextFromPage(PdfReader reader, int page, bool renderImage, iTextSharp.text.pdf.parser.ITextExtractionStrategy strategy, Rectangle textRectangle)
    {
        return PdfTextExtractor.GetTextFromPage(reader, page, renderImage, strategy, textRectangle, null);
    }
}
```

