using System;
using System.Collections.Generic;
using System.IO;
using iTextSharp.text;
using iTextSharp.text.pdf;

public class PdfPageExtractor
{
    public List<XObject> GetImagesFromPage(string pdfPath, int pageNumber)
    {
        List<XObject> images = new List<XObject>();

        using (PdfReader reader = new PdfReader(pdfPath))
        {
            PdfDictionary page = reader.GetPageN(pageNumber);
            PdfDictionary resources = page.GetAsDict(PdfName.RESOURCES);
            if (resources != null)
            {
                PdfArray xObjects = resources.GetAsArray(PdfName.XOBJECT);
                if (xObjects != null)
                {
                    foreach (PdfObject xObject in xObjects.ArrayList)
                    {
                        if (xObject is PdfDictionary && ((PdfDictionary)xObject).Get(PdfName.SUBTYPE) == PdfName.IMAGE)
                        {
                            images.Add(xObject);
                        }
                    }
                }
            }
        }

        return images;
    }

    public List<string> GetHyperlinksFromPage(string pdfPath, int pageNumber)
    {
        List<string> hyperlinks = new List<string>();

        using (PdfReader reader = new PdfReader(pdfPath))
        {
            PdfDictionary page = reader.GetPageN(pageNumber);
            PdfDictionary annotations = page.GetAsDict(PdfName.ANNOTS);
            if (annotations != null)
            {
                foreach (PdfObject annotation in annotations.ArrayList)
                {
                    PdfDictionary annotDict = (PdfDictionary)annotation;
                    if (annotDict.Get(PdfName.SUBTYPE) == PdfName.LINK)
                    {
                        PdfDictionary action = annotDict.GetAsDict(PdfName.A);
                        if (action != null)
                        {
                            PdfString uri = action.GetAsString(PdfName.URI);
                            if (uri != null)
                            {
                                hyperlinks.Add(uri.ToUnicodeString());
                            }
                        }
                    }
                }
            }
        }

        return hyperlinks;
    }
}

class Program
{
    static void Main(string[] args)
    {
        string pdfPath = @"C:\Users\Kris\test.pdf";
        int pageNumber = 1; // Change this to the page number you want to extract from

        PdfPageExtractor extractor = new PdfPageExtractor();

        // Extract images
        List<XObject> images = extractor.GetImagesFromPage(pdfPath, pageNumber);
        Console.WriteLine("Images on page {0}:", pageNumber);
        foreach (XObject image in images)
        {
            Console.WriteLine(image);
        }

        // Extract hyperlinks
        List<string> hyperlinks = extractor.GetHyperlinksFromPage(pdfPath, pageNumber);
        Console.WriteLine("Hyperlinks on page {0}:", pageNumber);
        foreach (string hyperlink in hyperlinks)
        {
            Console.WriteLine(hyperlink);
        }
    }
}
```
