Code: using System.Collections.Generic;
using UglyToad.PdfPig;
using UglyToad.PdfPig.DocumentLayoutAnalysis.TextExtractor;
using UglyToad.PdfPig.DocumentLayoutAnalysis.WordExtractor;
using UglyToad.PdfPig.DocumentLayoutAnalysis;

public class PdfLayoutAnalyzer
{
    public List<TextBlock> AnalyzeLayout(string filePath, int pageNumber)
    {
        using var document = new PdfDocument(filePath);
        var page = document.GetPage(pageNumber);

        var wordExtractor = new NearestNeighbourWordExtractor();
        var words = wordExtractor.ExtractWords(page.Letters);

        var segmenter = new PageSegmenter();
        var segments = segmenter.Segment(page, words);

        var orderDetector = new ReadingOrderDetector();
        var readingOrder = orderDetector.Detect(page, segments);

        return readingOrder;
    }
}
