using UglyToad.PdfPig.Writer.Builder;
using UglyToad.PdfPig.Writer.Objects;
using UglyToad.PdfPig.Writer.PageBuilder;

public class PdfCreator
{
    public void CreatePdf(string outputFilePath)
    {
        // Create a new PDF document builder
        var documentBuilder = new PdfDocumentBuilder();

        // Add a new page
        var pageBuilder = new PageBuilder();
        documentBuilder.AddPage(pageBuilder);

        // Register a standard 14 font
        var font = StandardFonts.TimesRoman;
        documentBuilder.RegisterFont(font);

        // Write multiple lines of text at different positions
        var textBuilder = new TextBuilder();
        textBuilder.SetFont(font, 12);

        // First line of text
        textBuilder.SetPosition(10, 700);
        textBuilder.Write("This is the first line of text.", out _, out _);

        // Second line of text
        textBuilder.SetPosition(10, 680);
        textBuilder.Write("This is the second line of text.", out _, out _);

        // Third line of text
        textBuilder.SetPosition(10, 660);
        textBuilder.Write("This is the third line of text.", out _, out _);

        // Build the document
        documentBuilder.Build(outputFilePath);
    }
}
