Code: using UglyToad.PdfPig.Writer;
using UglyToad.PdfPig.Writer.Builder;
using UglyToad.PdfPig.Writer.Objects;
using UglyToad.PdfPig.Writer.PageBuilder;

public class PdfPainter
{
    public void DrawShapes(string outputFilePath, int pageWidth, int pageHeight)
    {
        // Create a new PDF page builder
        var pageBuilder = new PageBuilder();

        // Set the page size
        pageBuilder.SetPageSize(pageWidth, pageHeight);

        // Create a graphics state
        var graphicsState = new GraphicsState();

        // Configure line width and color for drawing
        var lineWidth = 2f;
        var lineColor = Color.Red;

        // Draw a line
        pageBuilder.GraphicsState = graphicsState;
        pageBuilder.SetLineWidth(lineWidth);
        pageBuilder.SetStrokeColor(lineColor);
        pageBuilder.MoveTo(100, 500);
        pageBuilder.LineTo(300, 300);
        pageBuilder.Stroke();

        // Draw a rectangle
        lineWidth = 3f;
        lineColor = Color.Blue;

        pageBuilder.GraphicsState = graphicsState;
        pageBuilder.SetLineWidth(lineWidth);
        pageBuilder.SetStrokeColor(lineColor);
        pageBuilder.AppendRectangle(200, 200, 100, 100);
        pageBuilder.Stroke();

        // Build the page
        var page = pageBuilder.Build();

        // Create a new PDF document builder
        var documentBuilder = new PdfDocumentBuilder();

        // Add the page to the document
        documentBuilder.AddPage(page);

        // Build the document
        documentBuilder.Build(outputFilePath);
    }
}
