Code: using System.Collections.Generic;
using System.IO;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;
using UglyToad.PdfPig.Writer;

public class PdfMerger
{
    public byte[] MergePdfFiles(IReadOnlyList<string> filePaths)
    {
        using var documentBuilder = new PdfDocumentBuilder();

        foreach (var filePath in filePaths)
        {
            using var currentDocument = new PdfDocument(filePath);
            foreach (var page in currentDocument.GetPages())
            {
                documentBuilder.AddPage(page);
            }
        }

        using var ms = new MemoryStream();
        documentBuilder.Build(ms);
        return ms.ToArray();
    }
}
