Code: using System;
using System.Collections.Generic;
using System.IO;
using iTextSharp.text.pdf;
using iTextSharp.text.pdf.parser;

public class WordExtractor
{
    public Dictionary<int, List<string>> GetWordsForPage(string pdfPath)
    {
        var wordsByPage = new Dictionary<int, List<string>>();

        using (var reader = new PdfReader(pdfPath))
        {
            for (var page = 1; page <= reader.NumberOfPages; page++)
            {
                var words = new List<string>();
                using (var strategy = new LocationTextExtractionStrategy())
                {
                    var text = PdfTextExtractor.GetTextFromPage(reader, page, strategy);
                    // Split the text into words. This is a simple space-based split and might not work perfectly for all PDFs.
                    words = new List<string>(text.Split(' '));
                }
                wordsByPage[page] = words;
            }
        }

        return wordsByPage;
    }
