using System.Collections.Generic;
using System.IO;
using iTextSharp.text;
using iTextSharp.text.pdf;
using iTextSharp.text.pdf.parser;

public class DocumentLayoutAnalyzer
{
    public List<string> AnalyzeLayout(string pdfPath)
    {
        var extractedTextBlocks = new List<string>();

        using (var reader = new PdfReader(pdfPath))
        {
            for (var page = 1; page <= reader.NumberOfPages; page++)
            {
                var blocks = ExtractTextBlocks(reader, page);
                foreach (var block in blocks)
                {
                    extractedTextBlocks.Add(block);
                }
            }
        }

        return extractedTextBlocks;
    }

    private List<string> ExtractTextBlocks(PdfReader reader, int pageNumber)
    {
        var textBlocks = new List<string>();

        using (var strategy = new LocationTextExtractionStrategy())
        {
            string pageText = PdfTextExtractor.GetTextFromPage(reader, pageNumber, strategy);
            string[] lines = pageText.Split(new[] { "\r\n", "\r", "\n" }, StringSplitOptions.None);

            foreach (string line in lines)
            {
                // Here you can add logic to determine the reading order of the text blocks
                // For simplicity, we're just adding each line as a separate block
                textBlocks.Add(line);
            }
        }

        return textBlocks;
    }
}
