Code: using System;
using System.IO;
using iTextSharp.text;
using iTextSharp.text.pdf;

public class PdfPageBuilder
{
    private Document document;
    private PdfWriter writer;
    private PdfContentByte contentByte;

    public PdfPageBuilder(string outputPath)
    {
        document = new Document();
        writer = PdfWriter.GetInstance(document, new FileStream(outputPath, FileMode.Create));
        document.Open();
        contentByte = writer.DirectContent;
    }

    public void DrawLine(float x1, float y1, float x2, float y2, float lineWidth, BaseColor lineColor)
    {
        contentByte.SetLineWidth(lineWidth);
        contentByte.SetColorStroke(lineColor);
        contentByte.MoveTo(x1, y1);
        contentByte.LineTo(x2, y2);
        contentByte.Stroke();
    }

    public void DrawRectangle(float x1, float y1, float width, float height, float lineWidth, BaseColor lineColor, BaseColor fillColor)
    {
        contentByte.SetLineWidth(lineWidth);
        contentByte.SetColorStroke(lineColor);
        contentByte.SetColorFill(fillColor);
        contentByte.Rectangle(x1, y1, width, height);
        contentByte.FillStroke();
    }

    public void CloseDocument()
    {
        document.Close();
    }
}
