        var filePath = @"C:\Users\Kris\test.pdf";
        var pageNumber = 1;

        var images = extractor.GetImagesFromPage(filePath, pageNumber);
        var hyperlinks = extractor.GetHyperlinksFromPage(filePath, pageNumber);

