using iText.Kernel.Colors;
using iText.Kernel.Font;
using iText.Kernel.Geom;
using iText.Kernel.Pdf;
using iText.Layout;
using iText.Layout.Element;
using iText.Layout.Properties;

namespace PdfCreatorExample
{
    public class PdfCreator
    {
        public void CreatePdfWithText(string filePath, string title)
        {
            using PdfWriter writer = new PdfWriter(filePath);
            using PdfDocument pdfDoc = new PdfDocument(writer);
            Document doc = new Document(pdfDoc);

            // Add a title
            Paragraph titleParagraph = new Paragraph(title)
                .SetTextAlignment(iText.Layout.Properties.TextAlignment.CENTER)
                .SetFontSize(18);
            doc.Add(titleParagraph);

            // Create a new page with a size of 210 x 297 mm (A4)
            DirectDocumentContext context = new DirectDocumentContext(pdfDoc, new PageSize(PageSize.A4));
            Document newDoc = new Document(context);

            // Register the font
            IFont font = FontFactory.CreateFont("Arial");
            newDoc.Add(new Paragraph("This is a test document created with iText7."))
                .SetFont(font)
                .SetFontSize(12);

            // Define positions for the text
            Rectangle rect1 = new Rectangle(50, 750, 150, 50);
            Rectangle rect2 = new Rectangle(350, 750, 150, 50);
            Rectangle rect3 = new Rectangle(50, 700, 150, 50);

            // Write text to different positions
            Paragraph paragraph1 = new Paragraph("Text 1")
                .SetTextAlignment(TextAlignment.LEFT)
                .SetFontSize(12)
                .SetFont(font);
            newDoc.Add(new Paragraph("Line 1")
                .SetTextAlignment(TextAlignment.LEFT)
                .SetFontSize(12)
                .SetFont(font)
                .SetPosition(rect1));
            newDoc.Add(paragraph1);

            Paragraph paragraph2 = new Paragraph("Text 2")
                .SetTextAlignment(TextAlignment.LEFT)
                .SetFontSize(12)
                .SetFont(font);
            newDoc.Add(new Paragraph("Line 2")
                .SetTextAlignment(TextAlignment.LEFT)
                .SetFontSize(12)
                .SetFont(font)
                .SetPosition(rect2));
            newDoc.Add(paragraph2);

            Paragraph paragraph3 = new Paragraph("Text 3")
                .SetTextAlignment(TextAlignment.LEFT)
                .SetFontSize(12)
                .SetFont(font);
            newDoc.Add(new Paragraph("Line 3")
                .SetTextAlignment(TextAlignment.LEFT)
                .SetFontSize(12)
                .SetFont(font)
                .SetPosition(rect3));
            newDoc.Add(paragraph3);

            // Close the document and add the new page to the main document
            newDoc.Close();
            doc.Add(new Area(new Rectangle(50, 700, 900, 800))
                .SetBackgroundColor(ColorConstants.WHITE)
                .SetFixedPosition(50, 700));
            doc.Add(new Area(new Rectangle(0, 0, 900, 800))
                .SetBackgroundColor(ColorConstants.WHITE)
                .SetFixedPosition(0, 0));
            doc.Add(new Paragraph("This is a new page added to the document."));

            doc.Close();
        }
    }
}
