```csharp
using System;
using System.IO;
using iText.Kernel.Colors;
using iText.Kernel.Geom;
using iText.Kernel.Pdf;
using iText.Layout;
using iText.Layout.Element;
using iText.Layout.Properties;
using iText.Text;
using iText.IO;
using iText.IO.Image;
using iText.IO.Source;
using PdfExtractorExample;
using PdfMergerExample;

namespace PdfPig
{
    class Program
    {
        static void Main(string[] args)
        {
            // Read metadata from an input PDF file
            string inputPdfPath = @"C:\Users\Kris\test.pdf";
            using (PdfDocument inputPdfDoc = new PdfDocument(new PdfReader(inputPdfPath)))
            {
                Console.WriteLine($"Document Information: {inputPdfDoc.GetDocumentInfo()}");
            }

            // Extract text and words from a PDF page
            using (PdfDocument inputPdfDoc = new PdfDocument(new PdfReader(inputPdfPath)))
            {
                string text = PdfTextExtractor.ExtractTextFromPage(inputPdfDoc, 1);
                Console.WriteLine("Text on the first page:");
                Console.WriteLine(text);

                string[] words = PdfTextExtractor.ExtractWordsFromPage(inputPdfDoc, 1).Select(w => w.GetText().ToString()).ToArray();
                Console.WriteLine("Words on the first page:");
                Console.WriteLine(string.Join(" ", words));
            }

            // Analyze layout and create a new PDF with text and shapes
            ShapeCreator.CreatePdfWithShape("output_shape.pdf");
            string outputShapePdfPath = "output_shape.pdf";

            using (PdfDocument outputShapePdfDoc = new PdfDocument(new PdfWriter(outputShapePdfPath)))
            {
                Document document = new Document(outputShapePdfDoc);

                // Add text to the new PDF document
                Paragraph textParagraph = new Paragraph("This is a new PDF document with text.");
                textParagraph.SetTextAlignment(TextAlignment.CENTER);
                document.Add(textParagraph);

                // Add shapes to the new PDF document
                ShapeCreator.DrawRectangle(outputShapePdfDoc, 50, 700, 150, 50, new Color(255, 0, 0), 2.5f);
                ShapeCreator.DrawRectangle(outputShapePdfDoc, 350, 700, 150, 50, new Color(0, 255, 0), 2.5f);
                ShapeCreator.DrawLine(outputShapePdfDoc, 50, 750, 350, 750, new Color(0, 0, 0), 1.5f);

                document.Close();
                outputShapePdfDoc.Close();
            }

            // Merge PDF files
            string[] inputMergePdfPaths = new string[] { @"C:\Users\Kris\test.pdf", outputShapePdfPath };
            string outputMergePdfPath = @"C:\Users\Kris\merged.pdf";
            byte[] mergedPdfBytes = PdfMerger.MergePdfFiles(inputMergePdfPaths, outputMergePdfPath);

            // Write the merged PDF document to a file for further processing.
            File.WriteAllBytes(outputMergePdfPath, mergedPdfBytes);

            Console.WriteLine("PDF operations completed.");
        }
    }
}
