                    var textBlocks = textExtractor.Extract(TextExtractionMode.Layout);

                    var contentText = string.Join(" ", textBlocks.Select(x => x.Text));
                    var words = Regex.Split(contentText, @"\s+");

                    var tesseractEngine = new Engine("tesseract.exe", new Config());
                    tesseractEngine.Init();
                    tesseractEngine.SetPageSegMode(PageSegMode.PSM_AUTO);
