    public class PdfDocumentCreator
    {
        public void CreatePdfFile(string outputFilePath, int numLines, int linesPerRow)
        {
            var writer = new PdfWriter(outputFilePath);
            using (var pdf = new PdfDocument(writer))
            {
                var document = new Document(pdf);

                var standard14Font = PdfFontFactory.CreateFont("Standard14", BaseColor.BLACK);

                for (int pageNumber = 1; pageNumber <= 1; pageNumber++)
                {
                    var page = document.AddNewPage();

                    for (int rowNumber = 0; rowNumber < linesPerRow; rowNumber++)
                    {
                        for (int lineNumber = 0; lineNumber < numLines; lineNumber++)
                        {
                            var text = new Paragraph("Line " + (lineNumber + 1) + " in row " + (rowNumber + 1));
                            text.SetFont(standard14Font);

                            var xPosition = 50; // You can adjust the x position as needed
                            var yPosition = 100 + (lineNumber * 20); // You can adjust the y position and the line spacing as needed

                            text.SetTextAlign(iText.Layout.Properties.TextAlign.LEFT);
                            page.Add(text);
                        }
                    }
                }

                document.Close();
            }
        }
    }
}
