using iText.Kernel.Colors;
using iText.Kernel.Geom;
using iText.Kernel.Pdf;
using iText.Layout;
using iText.Layout.Element;

namespace PdfShapeCreatorExample
{
    public class PdfShapeCreator
    {
        public void CreatePdfFileWithShapes(string outputFilePath, int pageNumber, float width, float height, int lines, int rectangles)
        {
            using (var writer = new PdfWriter(outputFilePath))
            {
                using (var pdf = new PdfDocument(writer))
                {
                    var document = new Document(pdf);
                    document.SetDefaultFont(PdfFontFactory.CreateFont("Standard14"));

                    if (pageNumber < 1) throw new ArgumentOutOfRangeException(nameof(pageNumber), "Invalid page number");

                    var page = pdf.GetPage(pageNumber);
                    using (var pageBuilder = new PdfPageBuilder(page))
                    {
                        pageBuilder.DirectContent.BeginText();
                        pageBuilder.DirectContent.SetFontAndSize(PdfFontFactory.CreateFont("Standard14"), 12);
                        pageBuilder.DirectContent.ShowText("Drawing shapes on page " + pageNumber);
                        pageBuilder.DirectContent.EndText();

                        for (int lineIndex = 0; lineIndex < lines; lineIndex++)
                        {
                            DrawLine(pageBuilder, new Rectangle(50, 100 + lineIndex * 20, 100, 20), ColorConstants.RED, 2);
                        }

                        for (int rectangleIndex = 0; rectangleIndex < rectangles; rectangleIndex++)
                        {
                            DrawRectangle(pageBuilder, new Rectangle(50 + rectangleIndex * 150, 250, 100, 100), ColorConstants.BLUE, 4);
                        }

                        document.Close();
                    }
                }
            }

            void DrawLine(PdfPageBuilder pageBuilder, Rectangle rectangle, Color color, float lineWidth)
            {
                using (var line = new Line(rectangle.GetLeft(), rectangle.GetTop(), rectangle.GetRight(), rectangle.GetTop()))
                {
                    line.SetLineWidth(lineWidth);
                    line.SetColor(color);
                    pageBuilder.DirectContent.Add(line);
                }
            }

            void DrawRectangle(PdfPageBuilder pageBuilder, Rectangle rectangle, Color color, float lineWidth)
            {
                using (var rectangleShape = new Rectangle(rectangle).SetFillColor(ColorConstants.WHITE).SetBorderColor(color).SetBorderWidth(lineWidth))
                {
                    pageBuilder.DirectContent.Add(rectangleShape);
                }
            }

            public void CreatePdfFileWithShapes(string filePath, int pageNumber, float width, float height, int lines, int rectangles)
            {
                CreatePdfFileWithShapes(filePath, pageNumber, width, height, lines, rectangles);
            }

            public static void Main(string[] args)
            {
                int lines = 3;
                int rectangles = 3;
                PdfShapeCreator example = new PdfShapeCreator();
                example.CreatePdfFileWithShapes("output.pdf", 1, width: 595, height: 846, lines: 3, rectangles: 3);
            }
        }
