using System.Collections.Generic;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;

namespace PdfPigExample
{
    public class PdfReader
    {
        public PdfDocument ReadPdfFile(string filePath)
        {
            using (var document = new PdfDocument(filePath))
            {
                return document;
            }
        }

        public void ReadDocumentInformation(string filePath, Action<int, string, string, string, string> printInformation)
        {
            using (var document = ReadPdfFile(filePath))
            {
                printInformation(document.PageCount, document.Version, document.Info.Title, document.Info.Author, document.Info.Producer);
            }
        }

        public Dictionary<int, string> ExtractTextByPage(string filePath)
        {
            using (var document = ReadPdfFile(filePath))
            {
                var textByPage = new Dictionary<int, string>();

                for (int pageNumber = 0; pageNumber < document.PageCount; pageNumber++)
                {
                    using (var page = document.GetPage(pageNumber))
                    {
                        using (var extractor = new ContentOrderTextExtractor(page))
                        {
                            textByPage.Add(pageNumber + 1, extractor.GetText());
                        }
                    }
                }

                return textByPage;
            }
        }
    }
}
