namespace PdfPigExample
{
    public class PdfReader
    {
        public PdfDocument ReadPdfFile(string filePath)
        {
            using (var document = new PdfDocument(filePath))
            {
                return document;
            }
        }

        public void ReadDocumentInformation(string filePath, Action<int, string, string, string, string> printInformation)
        {
            using (var document = ReadPdfFile(filePath))
            {
                printInformation(document.PageCount, document.Version, document.Info.Title, document.Info.Author, document.Info.Producer);
            }
        }

        public Dictionary<int, List<string>> ExtractTextByWord(string filePath)
        {
            using (var document = ReadPdfFile(filePath))
            {
                var wordsByPage = new Dictionary<int, List<string>>();

                for (int pageNumber = 0; pageNumber < document.PageCount; pageNumber++)
                {
                    using (var page = document.GetPage(pageNumber))
                    {
                        using (var extractor = new NearestNeighbourWordExtractor(page, new TextRecognitionOptions()))
                        {
                            var words = extractor.GetTextContent().ToList();
                            wordsByPage.Add(pageNumber + 1, words);
                        }
                    }
                }

                return wordsByPage;
            }
        }

        public List<string> GetWordsForPage(int pageNumber, Dictionary<int, List<string>> wordsByPage)
        {
            return wordsByPage[pageNumber];
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            var pdfReader = new PdfReader();
            string filePath = @"C:\Users\Kris\test.pdf";

            pdfReader.ReadDocumentInformation(filePath, (pageCount, version, title, author, producer) =>
            {
                Console.WriteLine($"Page count: {pageCount}");
                Console.WriteLine($"PDF version: {version}");
                Console.WriteLine($"Title: {title}");
                Console.WriteLine($"Author: {author}");
                Console.WriteLine($"Producer: {producer}");
            });

            var wordsByPage = pdfReader.ExtractTextByWord(filePath);

            Console.WriteLine("\nWords by page:");
