            mainDoc.Add(new Paragraph("This is the original document.").SetTextAlignment(TextAlignment.CENTER));
            newDoc.Close();

            // Add the title, the new page, and the background to the main document
            mainDoc.Add(titleParagraph);
            mainDoc.Add(new Area(new Rectangle(50, 700, 900, 800))
