using iText.IO.Source;
using iText.Kernel.Pdf.DirectObject;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace PdfMergerExample
{
    public static class PdfMerger
    {
        public static byte[] MergePdfFiles(string[] inputPdfPaths, string outputPdfPath)
        {
            using PdfDocument outputPdfDoc = new PdfDocument(new PdfWriter(outputPdfPath));
            Document document = new Document(outputPdfDoc);

            foreach (string inputPdfPath in inputPdfPaths)
            {
                using (PdfDocument inputPdfDoc = new PdfDocument(new PdfReader(inputPdfPath)))
                {
                    for (int i = 1; i <= inputPdfDoc.GetNumberOfPages(); i++)
                    {
                        PdfPage page = inputPdfDoc.GetPage(i);
                        outputPdfDoc.AddNewPage();
                        PdfPage newPage = outputPdfDoc.GetLastPage();
                        newPage.Add(new DirectObject() { Stream = new MemoryStream(GetImageBytes(inputPdfDoc, page)) });
                    }
                }
            }

            document.Close();
            outputPdfDoc.Close();

            return File.ReadAllBytes(outputPdfPath);
        }

        private static byte[] GetImageBytes(PdfDocument inputPdfDoc, PdfPage page)
        {
            ImageData imageData = page.GetImageResources().GetImageData(0);
            using (MemoryStream imageStream = new MemoryStream())
            {
                imageData.WriteTo(imageStream);
                return imageStream.ToArray();
            }
        }
    }
}
