    class Program
    {
        static void Main(string[] args)
        {
            // Read metadata from an input PDF file
            string inputPdfPath = @"C:\Users\Kris\test.pdf";
            using (PdfDocument inputPdfDoc = new PdfDocument(new PdfReader(inputPdfPath)))
            {
                Console.WriteLine($"Document Information: {inputPdfDoc.GetDocumentInfo()}");
            }

            // Extract text and words from a PDF page
            using (PdfDocument inputPdfDoc = new PdfDocument(new PdfReader(inputPdfPath)))
            {
                string text = PdfTextExtractor.ExtractTextFromPage(inputPdfDoc, 1);
