                textParagraph.SetTextAlignment(TextAlignment.CENTER);
                document.Add(textParagraph);

                // Add shapes to the new PDF document
                ShapeCreator.DrawRectangle(outputShapePdfDoc, 50, 700, 150, 50, new Color(255, 0, 0), 2.5f);
                ShapeCreator.DrawRectangle(outputShapePdfDoc, 350, 700, 150, 50, new Color(0, 255, 0), 2.5f);
                ShapeCreator.DrawLine(outputShapePdfDoc, 50, 750, 350, 750, new Color(0, 0, 0), 1.5f);

                document.Close();
                outputShapePdfDoc.Close();
