    public class PdfTextExtractor
    {
        public Dictionary<int, string> ExtractTextByPage(string pdfPath)
        {
            var extractedTexts = new Dictionary<int, string>();

            using (var document = new Document(pdfPath))
            {
                for (int i = 1; i <= document.PageCount; i++)
                {
                    using (var page = document.GetPage(i))
                    {
                        var content = new ContentStream(page.ContentStream);
                        var extractor = new ContentOrderTextExtractor();
                        extractedTexts[i] = extractor.ExtractText(content);
                    }
                }
            }

            return extractedTexts;
        }
    }
}
