Code: using System;
using System.Collections.Generic;
using System.IO;
using Tesseract;
using UglyToad.PdfPig;

namespace PdfPigExample
{
    public class PdfWordExtractor
    {
        public Dictionary<int, List<string>> GetWordsForPage(string pdfPath)
        {
            var wordsByPage = new Dictionary<int, List<string>>();

            using (var document = new Document(pdfPath))
            {
                for (int i = 1; i <= document.PageCount; i++)
                {
                    using (var page = document.GetPage(i))
                    {
                        var pageContent = new Image(page.GetImage());

                        using (var engine = new Engine("tesseract.exe", new Config()))
                        {
                            engine.Init();
                            engine.SetPageSegmentMode(PageSegMode.PSM_AUTO);
                            engine.SetVariable("tessedit_char_whitelist", "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ");

                            var pageText = engine.Process(pageContent).GetText();
                            engine.End();

                            wordsByPage[i] = pageText.Split(' ').ToList();
                        }
                    }
                }
            }

            return wordsByPage;
        }
    }
}
