Code: using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.RegularExpressions;
using Tesseract;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;
using UglyToad.PdfPig.DocumentLayoutAnalysis.TextExtractor;
using UglyToad.PdfPig.DocumentLayoutAnalysis.TextExtractor.LayoutAnalyzers;

namespace PdfPigExample
{
    public class AdvancedPdfAnalyzer
    {
        public Dictionary<int, string> GetLayoutTextForPage(string pdfPath, int pageNumber)
        {
            using (var document = new Document(pdfPath))
            {
                if (pageNumber < 1 || pageNumber > document.PageCount)
                {
                    throw new ArgumentOutOfRangeException(nameof(pageNumber));
                }

                using (var page = document.GetPage(pageNumber))
                {
                    var textExtractor = new TextExtractor(page.ContentStream, page.MediaBox, true);
                    var textBlocks = textExtractor.Extract(TextExtractionMode.Layout);

                    var contentText = string.Join(" ", textBlocks.Select(x => x.Text));
                    var words = Regex.Split(contentText, @"\s+");

                    var tesseractEngine = new Engine("tesseract.exe", new Config());
                    tesseractEngine.Init();
                    tesseractEngine.SetPageSegMode(PageSegMode.PSM_AUTO);
                    tesseractEngine.SetVariable("tessedit_char_whitelist", "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ");

                    var layoutResult = tesseractEngine.Process(page.GetImage(), pageNumber.ToString()).GetText();
                    tesseractEngine.End();

                    return new Dictionary<int, string> { { pageNumber, layoutResult } };
                }
            }
        }
    }
}
