Code: using System.Collections.Generic;
using System.IO;
using iText.Common.Exceptions;
using iText.Common;
using iText.Kernel.Pdf;
using iText.Layout.Element;
using iText.Layout;

namespace PdfExtractorExample
{
    public class PdfExtractor
    {
        public List<string> GetImagesFromPage(string filePath, int pageNumber)
        {
            using (PdfReader reader = new PdfReader(filePath))
            {
                IList<Image> images = reader.GetPageN(pageNumber).GetImages();
                List<string> imagePaths = new List<string>();

                foreach (Image image in images)
                {
                    string imagePath = Path.Combine(Path.GetDirectoryName(filePath), image.GetReference().GetName());
                    imagePaths.Add(imagePath);
                }

                return imagePaths;
            }
        }

        public List<string> GetHyperlinksFromPage(string filePath, int pageNumber)
        {
            List<string> hyperlinks = new List<string>();

            using (PdfReader reader = new PdfReader(filePath))
            {
                IList<IAnnotation> annotations = reader.GetPageN(pageNumber).Annotations;

                foreach (IAnnotation annotation in annotations)
                {
                    if (annotation is IAnnotation2 annotation2 && annotation2.GetSubtype() == AnnotationSubtype.LINK)
                    {
                        hyperlinks.Add(annotation2.GetAction().GetLink().GetUrlPath());
                    }
                }
            }

            return hyperlinks;
        }
    }
}
