Code: using System;
using System.IO;
using iText.Kernel.Pdf;
using iText.Kernel.Pdf.Reader;
using iText.Kernel.Pdf.Writer;
using iText.Layout;

namespace PdfMergerExample
{
    public class PdfMerger
    {
        public byte[] MergePdfFiles(string mainFilePath, params string[] additionalFilesPaths)
        {
            using (MemoryStream outputStream = new MemoryStream())
            {
                using (PdfReader reader = new PdfReader(mainFilePath));
                using (PdfWriter writer = new PdfWriter(outputStream))
                {
                    using (PdfDocument document = new PdfDocument(writer))
                    {
                        document.Add(new PdfDocument(new PdfReader(mainFilePath)));

                        foreach (string additionalFilePath in additionalFilesPaths)
                        {
                            using (PdfReader reader2 = new PdfReader(additionalFilePath))
                            {
                                for (int pageNumber = 1; pageNumber <= reader2.NumberOfPages; pageNumber++)
                                {
                                    document.AddPage(new PdfImportedPage(reader2, pageNumber));
                                }
                            }
                        }

                        document.Close();
                        reader.Close();
                        writer.Close();

                        return outputStream.ToArray();
                    }
                }
            }
        }
    }
}
