using UglyToad.PdfPig.Direct.Elements;

namespace PdfPigDemo
{
    public class PdfTextWriter
    {
        public void WriteToFile(string filePath)
        {
            using (var document = new PdfDocumentBuilder())
            {
                document.SetAuthor("Kris");
                document.SetTitle("My First PDF");
                document.Open();

                // Add a new page to the document
                document.AddNewPage();

                // Register a standard font
                var font = new Font("Helvetica", 14);

                // Write the text to the PDF
                var xPosition = 50;
                var yPosition = 700;

                document.BeginText();
                document.SetFont(font);

                // Write the first line of text
                document.WriteText("Hello, World!");
                xPosition += document.GetStringWidth("Hello, World!");

                // Write the second line of text
                document.WriteText("This is a demonstration!");");
                xPosition += document.GetStringWidth("This is a demonstration!");");

                // Write the third line of text
                document.WriteText("Please check it out!");");
                xPosition += document.GetStringWidth("Please check it out!");");

                // End the text writing process
                document.EndText();

                // Save and close the document
                document.Save(filePath);
                document.Close();
            }
        }
    }
}
