```csharp
using System;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Direct;
using UglyToad.PdfPig.Direct.Elements;

namespace PdfPigDemo
{
    public class PdfShapeWriter
    {
        public void DrawShapes(string filePath)
        {
            using (var document = new PdfDocument())
            {
                document.Open();

                // Add a new page to the document
                var page = document.AddNewPage();
                var xPosition = 50;
                var yPosition = 700;

                // Draw a red line
                using (var graphics = new GraphicsObject())
                using (var stroke = new SolidColorBrush(new DeviceRgbColor(1.0f, 0.0f, 0.0f)))
                {
                    graphics.SetColor(stroke);
                    graphics.MoveTo(xPosition, yPosition);
                    graphics.LineTo(xPosition + 100, yPosition);
                    page.DirectContent.Add(graphics);
                }

                xPosition += 100;

                // Draw a green rectangle
                using (var graphics = new GraphicsObject())
                using (var fill = new SolidColorBrush(new DeviceRgbColor(0.0f, 1.0f, 0.0f)))
                using (var pen = new Pen(1.0f))
                {
                    graphics.SetColor(fill);
                    graphics.Rectangle(xPosition, yPosition, 100, 100);
                    page.DirectContent.Add(graphics);

                    graphics.SetColor(pen);
                    graphics.DrawRectangle(xPosition, yPosition, 100, 100);
                    page.DirectContent.Add(graphics);
                }

                document.Save(filePath);
                document.Close();
            }
        }
    }
}
```

