using System;
using System.Collections.Generic;
using System.IO;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Direct;
using UglyToad.PdfPig.Direct.Elements;
using System.Drawing.Imaging;
using System.Drawing;
using System.Linq;
using UglyToad.PdfPig.ContentStreams;

namespace PdfPigDemo
{
    class Program
    {
        static void Main(string[] args)
        {
            // Create a PdfExtractor instance for extracting images, hyperlinks, and text
            var pdfExtractor = new PdfExtractor();

            // Read metadata
            using (var document = new PdfDocument("C:/Users/Kris/test.pdf"))
            {
                Console.WriteLine("Metadata:");
                Console.WriteLine("Title: " + document.Info.Title);
                Console.WriteLine("Author: " + document.Info.Author);
                Console.WriteLine("Producer: " + document.Info.Producer);
                Console.WriteLine("Creation Date: " + document.Info.CreationDate);
                Console.WriteLine("Modification Date: " + document.Info.ModificationDate);
                Console.WriteLine();
            }

            // Extract text and words
            using (var document = new PdfDocument("C:/Users/Kris/test.pdf"))
            {
                document.Open();
                using (var textExtractor = new TextExtractor(document))
                {
                    Console.WriteLine("Text:");
                    Console.WriteLine(textExtractor.GetText());
                    Console.WriteLine();

                    Console.WriteLine("Words:");
                    foreach (var word in textExtractor.GetWords())
                    {
                        Console.WriteLine(word);
                    }
                    Console.WriteLine();
                }
                document.Close();
            }

            // Analyze layout using shapes
            using (var document = new PdfDocument("C:/Users/Kris/test.pdf"))
            {
                document.Open();
                using (var graphics = document.GetPage(0).GetGraphics())
                {
                    var shapes = graphics.GetShapes();
                    Console.WriteLine("Shapes:");
                    foreach (var shape in shapes)
                    {
                        Console.WriteLine(shape.Type);
                        Console.WriteLine("X position: " + shape.X);
                        Console.WriteLine("Y position: " + shape.Y);
                        Console.WriteLine("Width: " + shape.Width);
                        Console.WriteLine("Height: " + shape.Height);
                        Console.WriteLine();
                    }
                }
                document.Close();
            }

            // Create a new PDF with text and shapes
            var pdfShapeWriter = new PdfShapeWriter();
            pdfShapeWriter.DrawTextOnPage("Text on page.pdf", 1, "Hello World!");
            pdfShapeWriter.Save("TextOnPage.pdf");

            // Read images and hyperlinks from a page
            using (var document = new PdfDocument("C:/Users/Kris/TextOnPage.pdf"))
            {
                document.Open();
                var images = pdfExtractor.GetImagesFromPage(1);
                var hyperlinks = pdfExtractor.GetHyperlinksFromPage(1);

                Console.WriteLine("Extracted images from page 1 of TextOnPage.pdf:");
                foreach (var image in images)
                {
                    File.WriteAllBytes("image_" + 1 + ".png", image);
                    Console.WriteLine("Image " + 1 + " saved.");
                }

                Console.WriteLine("Extracted hyperlinks from page 1 of TextOnPage.pdf:");
                foreach (var hyperlink in hyperlinks)
                {
                    Console.WriteLine(hyperlink);
                }
                document.Close();
            }

            // Merge PDF files
            var pdfMerger = new PdfMerger();
            var mergedPdfAsByteArray = pdfMerger.MergePdfFiles("C:/Users/Kris/test.pdf", "C:/Users/Kris/TextOnPage.pdf");

            // Save the merged PDF to a file
            File.WriteAllBytes("merged.pdf", mergedPdfAsByteArray);
            Console.WriteLine("Merged PDF saved.");
        }
    }
}
