    private static void CreateNewDocument()
    {
        Document newDocument = new Document();

        iText.io.FontRegistry fontRegistry = new FontRegistry();
        IText.IO.Font.StandardFontRegistry stdFontRegistry = new StandardFontRegistry(fontRegistry);

        PdfFont font1 = PdfFontFactory.CreateFont("Helveta");
        IText.Layout.Font.StandardFont paragraphFont1 = new StandardFont(font1, 12);

        Paragraph paragraph1 = new Paragraph("Hello World!");
        paragraph1.SetFont(paragraphFont1);
        paragraph1.AddPosition(25f, 180f);

        newDocument.Add(paragraph1);

        Paragraph paragraph2 = new Paragraph("Welcome to our new PDF!");
        paragraph2.SetFont(paragraphFont1);
        paragraph2.AddPosition(85f, 650f);

        newDocument.Add(paragraph2);

        newDocument.Save("C:\\Users\\Kris\\test.pdf");
        Console.WriteLine("The PDF document has been saved!");
    }
}
