using iText.Kernel.Pdf;
using iText.Layout;
using iText.Layout.Element;
using iText.Layout.Property;
using java.io;
using java.util;
using System.Collections.Generic;

namespace PdfTextExtractor
{
    public class PdfTextExtractor
    {
        public Image[] GetImagesFromPage(string filePath, int pageNumber)
        {
            using (var reader = new PdfReader(filePath))
            {
                if (reader.IsOpen)
                {
                    using (var document = new Document())
                    {
                        var writer = PdfWriter.GetInstance(document, new FileStream(Path.GetTempFileName() + ".pdf"));
                        document.Open();
                        document.Add(new TextProgram(new Phrase("")).CreateText("Extracted Images")).SetTextAlignable(TextAlign.LEFT, TextAlign.TOP).Add();
                        document.NewPage();
                        document.Add(new Chunk("Extracted from page " + pageNumber + " of " + reader.NumberOfPages)).SetTextAlignable(TextAlign.CENTER, TextAlign.MIDDLE);
                        document.Add(new Area(new Rectangle(15, 750, reader.GetPageSize(pageNumber).GetWidth(), reader.GetPageSize(pageNumber).GetHeight())));
                        PdfCopy copy = new PdfCopy(document, new FileStream(Path.GetTempFileName() + "_copy.pdf", FileMode.Create, FileAccess.Write, FileShare.None));
                        document.Close();
                        reader.Close();
                        document = new Document(copy.GetOutputStream());

                        using (var pdfr = new PdfReader(filePath))
                        {
                            pdfr.SetPageSize(new Rectangle(reader.GetPageSize(pageNumber).Width, reader.GetPageSize(pageNumber).Height));
                            pdfr.SetPage(pageNumber);
                            document.SetPageSize(new Rectangle(reader.GetPageSize(pageNumber).Width, reader.GetPageSize(pageNumber).Height));
                            document.NewPage();
                            document.Add(pdfr.GetPage(pageNumber));
                            var images = new List<Image>();
                            for (int i = 1; i <= pdfr.NumberOfImages; i++)
                            {
                                if (pdfr.GetImage(i).GetType() == PdfObject.IMAGE_JPEG || pdfr.GetImage(i).GetType() == PdfObject.IMAGE_JPG)
                                {
                                    var image = pdfr.GetImage(i).CreateScaledCopy((float)document.DefaultCell().GetCssBox(0).GetWidth(), (float)document.DefaultCell().GetCssBox(0).GetHeight(), new Rectangle(15, 750, document.DefaultCell().GetCssBox(0).GetWidth(), document.DefaultCell().GetCssBox(0).GetHeight()));
                                    images.Add(image);
                                    document.Add(new Image(image).SetWidth((float)document.DefaultCell().GetCssBox(0).GetWidth()).SetHeight((float)document.DefaultCell().GetCssBox(0).GetHeight()).SetPosition(15, 750));
                                }
                            }
                            document.Close();
                            return images.ToArray();
                        }
                    }
                }
            }
            return new Image[0];
        }

        public List<string> GetHyperlinksFromPage(string filePath, int pageNumber)
        {
            using (var reader = new PdfReader(filePath))
            {
                if (reader.IsOpen)
                {
                    using (var document = new Document())
                    {
                        var writer = PdfWriter.GetInstance(document, new FileStream(Path.GetTempFileName() + "_links.pdf", FileMode.Create, FileAccess.Write, FileShare.None));
                        document.Open();
                        document.Add(new TextProgram(new Phrase("")).CreateText("Extracted Links")).SetTextAlignable(TextAlign.LEFT, TextAlign.TOP).Add();
                        document.NewPage();
                        document.Add(new Chunk("Extracted from page " + pageNumber + " of " + reader.NumberOfPages)).SetTextAlignable(TextAlign.CENTER, TextAlign.MIDDLE);
                        document.Add(new Area(new Rectangle(15, 750, reader.GetPageSize(pageNumber).GetWidth(), reader.GetPageSize(pageNumber).GetHeight())));
                        PdfCopy copy = new PdfCopy(document, new FileStream(Path.GetTempFileName() + "_copy.pdf", FileMode.Create, FileAccess.Write, FileShare.None));
                        document.Close();
                        reader.Close();
                        document = new Document(copy.GetOutputStream());

                        using (var pdfr = new PdfReader(filePath))
                        {
                            pdfr.SetPageSize(new Rectangle(reader.GetPageSize(pageNumber).Width, reader.GetPageSize(pageNumber).Height));
                            pdfr.SetPage(pageNumber);
                            document.SetPageSize(new Rectangle(reader.GetPageSize(pageNumber).Width, reader.GetPageSize(pageNumber).Height));
                            document.NewPage();
                            document.Add(pdfr.GetPage(pageNumber));

                            var links = new List<string>();
                            for (int i = 1; i <= pdfr.NumberOfAnnotations; i++)
                            {
                                var annotation = pdfr.GetAnnotation(i);
                                if (annotation is AnnotationLink annotationLink)
                                {
                                    links.Add(annotationLink.GetAction().GetDestination().GetNameValue());
                                    document.Add(new Text(annotationLink.GetLocation().GetX() + " " + annotationLink.GetLocation().GetY(), new Phrase(annotationLink.GetText()).SetFontSize(annotationLink.GetFontSize()))).SetColor(BaseColor.BLUE).Add();
                                }
                            }
                            document.Close();
                            return links;
                        }
                    }
                }
            }
            return new List<string>();
        }
    }
}
```

**Explanation:**

The `PdfTextExtractor` class demonstrates the extraction of images and hyperlinks from a specific page in a PDF file. The `GetImagesFromPage` method retrieves images by creating a temporary document and copying the specified PDF page to the new document. The images are then extracted and stored in an array. The `GetHyperlinksFromPage` method extracts hyperlinks by creating a temporary document, copying the specified PDF page, and then iterating through the annotations to find and extract hyperlinks. The hyperlinks are returned as a list of strings.
