using iText.io.source;
using iText.kernel.pdf;
using iText.kernel.stream;
using iText.io.util;
using iText.io.eventhandlers;
using java.io;
using java.util;
using System.Collections;

namespace MergePDF
{
    class MergePDF
    {
        public byte[] MergePdfFiles(string[] inputFilePaths, string outputFilePath)
        {
            PdfDocument sourceDocument = null, targetDocument = null;
            try
            {
                sourceDocument = new PdfDocument(new FileInputStream(inputFilePaths[0]));

                targetDocument = new PdfDocument(new FileStream(outputFilePath, FileMode.Create));

                for (int index = 1; index < inputFilePaths.Length; index++)
                {
                    PdfDocument readerDocument = new PdfDocument(new FileInputStream(inputFilePaths[index]));

