                        copyPages(sourceDocument, targetDocument, new PdfInternalResource(readerDocument.GetPageContent(i)).Stream, i);
                    }
                    readerDocument.Close();
                }

                readerDocument = new PdfDocument(new FileInputStream(inputFilePaths[0]));
                for (int i = 1; i < readerDocument.NumberOfPages; i++)
                    copyPages(targetDocument, targetDocument, new PdfInternalResource(readerDocument.GetPageContent(i)).Stream, i);

                sourceDocument.Close();
                targetDocument.Save();
                targetDocument.Close();

                byte[] outputBytes = new FileStream(outputFilePath, FileMode.Open, 0).ReadToEnd();
                return outputBytes;
            }
            catch (Exception ex)
            {
                Console.WriteLine("An error occurred while trying to merge PDFs: " + ex.Message);
                return null;
            }
        }

        private static void copyPages(PdfDocument sourceDocument, PdfDocument targetDocument, Stream targetStream, int targetPageIndex)
        {
            Rectangle box = new Rectangle(0, 0, sourceDocument.GetPageContent(targetPageIndex).GetWidth(), sourceDocument.GetPageContent(targetPageIndex).GetHeight());
            PdfCopy copy = new PdfCopy(sourceDocument, new FileOutputStream(string.Format("{0}_page_{1}.pdf", targetDocument.NumberOfDocuments, targetPageIndex)));
            copy.Add(new PdfDocumentReader().LoadDocument(sourceDocument.GetPageContent(targetPageIndex).ToStream()));
            copy.Add(copy.GetPages());
            copy.Close();
            targetDocument.Add(copy.GetPage(1));

            sourceDocument.GetPageContent(targetPageIndex).Dispose();
            targetDocument.GetOutputStream().Reset();
            targetDocument.GetOutputStream().Seek(0);
            targetDocument.GetOutputStream().Put(new RawConverter(targetStream).ConvertTo(iText.io.Stream.Stream.ByteArrayStreamFactory.CreateStream()));
            targetDocument.GetOutputStream().CleanUp();
            targetDocument.GetOutputStream().Flush();
        }
    }
}
```

This class offers a method called `MergePdfFiles` that accepts file paths and outputs a byte array containing the merged PDF document.

To use it, you need to have the iTextSharp library installed in your project. If you don't, you can download it from [here](https://itextpdf.com/en/downloads.aspx). Also, you need to use Java classes like `java.io.FileInputStream` and `java.io.FileOutputStream` in your C# project. You can add the Java Class Libraries (JAR files) to your project and use the classes.
