            using (var document = new PdfDocument("C:/Users/Kris/test.pdf"))
            {
                document.Open();

                var images = new List<byte[]>();
                var page = document.GetPage(pageNumber);

                // Extract images from the page
                using (var graphics = page.GetGraphics())
                {
                    var image = graphics.GetImage();
                    using (var imageStream = new MemoryStream())
                    {
                        image.Save(imageStream, ImageFormat.Png);
                        images.Add(imageStream.ToArray());
                    }
                }

                document.Close();
                return images;
            }
        }

        public List<string> GetHyperlinksFromPage(int pageNumber)
        {
            using (var document = new PdfDocument("C:/Users/Kris/test.pdf"))
            {
                document.Open();

                var hyperlinks = new List<string>();
                var page = document.GetPage(pageNumber);

                // Extract hyperlinks from the page
                using (var contentStream = page.ContentStream)
                {
                    foreach (var action in contentStream.Actions)
                    {
                        if (action is GoToAction goToAction)
                        {
                            hyperlinks.Add(goToAction.Destination.ToUri().AbsoluteUri);
                        }
                    }
                }

                document.Close();
                return hyperlinks;
            }
        }
    }
}
