using System;
using iText.Kernel.Font;
using iText.Kernel.Geom;
using iText.Kernel.Pdf;
using iText.Layout;
using iText.Layout.Element;
using iText.Layout.Properties;

namespace PdfPigExample
{
    public class PdfDocumentCreator
    {
        public void CreateNewPdf(string outputPath)
        {
            using (PdfDocument document = new PdfDocument(new PdfWriter(outputPath)))
            {
                Document pdfDoc = new Document(document);
                Chunk text = new Chunk("Hello World! This is a new PDF document.");
                Paragraph paragraph = new Paragraph(text).SetTextAlign(TextAlignment.CENTER).SetFontSize(14);
                Rectangle imageRectangle = new Rectangle(36, 36, 100, 20);

                // First page
                pdfDoc.Add(new Paragraph("Text on the first page.").SetTextAlign(TextAlignment.LEFT).SetFontSize(14));
                pdfDoc.Add(paragraph);
                pdfDoc.Add(new Paragraph("Text on the first page.").SetTextAlign(TextAlignment.CENTER).SetFontSize(14));

                // Register a font
                PdfFont font = PdfFontFactory.CreateFont("Standard14");

                // Second page
                pdfDoc.NewPage();
                text = new Chunk("Hello World! This is a new paragraph on the second page.").SetFont(font);
                Paragraph secondPageParagraph = new Paragraph(text).SetTextAlign(TextAlignment.LEFT).SetFontSize(14);
                pdfDoc.Add(secondPageParagraph);

                text = new Chunk("Registered font.").SetFont(font);
                Paragraph fontExampleParagraph = new Paragraph(text).SetTextAlign(TextAlignment.RIGHT).SetFontSize(14);
                pdfDoc.Add(fontExampleParagraph);

                text = new Chunk("Text block with image.").SetFont(font);
                Paragraph imageWithTextParagraph = new Paragraph(text).SetTextAlign(TextAlignment.LEFT).SetFontSize(14);

                pdfDoc.Add(new Text("Text block with image at: "));
                pdfDoc.Add(imageWithTextParagraph);
                pdfDoc.Add(new Image("image.jpg").SetImageScalingStrategy(ImageScalingStrategy.TILED).SetPosition(imageRectangle.GetBottomLeftX(), imageRectangle.GetBottomLeftY()));

                // Close the document
                pdfDoc.Close();
            }
        }
    }
}
```

