{
    static void Main(string[] args)
    {
        string outputPath = "output.pdf";
        string inputPath1 = @"C:\Users\Kris\test.pdf";
        string inputPath2 = @"C:\Users\Kris\anotherFile.pdf";

        using (PdfMerger merger = new PdfMerger())
        using (MemoryStream mergedPdf = new MemoryStream(merger.MergePdfFiles(inputPath1, inputPath2)))
        using (FileStream outputFile = new FileStream(outputPath, FileMode.Create))
        {
            outputFile.Write(mergedPdf.ToArray(), 0, mergedPdf.ToArray().Length);
        }

        Console.WriteLine("Merged PDF file created at: " + outputPath);
    }
}
