```csharp
using System;
using iText.Kernel.Pdf;
using iText.Layout;
using iText.Layout.Element;
using iText.Layout.Properties;
using iText.Kernel.Pdf.Annotation;
using iText.Kernel.Geom;
using iText.Kernel.Colors;
using iText.Kernel.Utils;
using System.Collections.Generic;
using System.IO;

namespace PdfPig
{
    class Program
    {
        static void Main(string[] args)
        {
            string testInputFile = @"C:\Users\Kris\test.pdf";
            string newPdfOutput = "new_output.pdf";
            string mergedPdfOutput = "merged_output.pdf";

            Console.WriteLine("Reading test.pdf metadata...");
            PdfMetadataReader metadataReader = new PdfMetadataReader(testInputFile);
            Console.WriteLine("Metadata read: " + metadataReader.GetMetadata());
            metadataReader.Close();

            Console.WriteLine("Extracting text and words...");
            PdfTextExtractor textExtractor = new PdfTextExtractor(new PdfReader(testInputFile));
            string extractedText = textExtractor.GetText();
            Console.WriteLine("Text extracted: " + extractedText);

            Console.WriteLine("Analyzing layout...");
            using (PdfDocument document = new PdfDocument(new PdfReader(testInputFile), new PdfWriter(Console.OpenOutput("layout_analysis.txt"))))
            {
                PdfLayoutAnalysisStrategy strategy = new PdfLayoutAnalysisStrategy();
                strategy.ProcessPageContent(document.GetPage(1));
                Console.WriteLine("Layout analysis: " + strategy.GetResult());
            }

            Console.WriteLine("Creating a new PDF...");
            CreateNewPdf(newPdfOutput, "New PDF Title");
            AddTextToNewPdf(newPdfOutput, "This is a new PDF created with iText7.");
            AddShapeToNewPdf(newPdfOutput, "Rectangle", 50, 50, 100, 100, ColorConstants.RED);
            AddShapeToNewPdf(newPdfOutput, "Line", 100, 100, 200, 200, ColorConstants.BLACK, 1.5f);

            Console.WriteLine("Merging PDFs...");
            MergePdfFiles(newPdfOutput, testInputFile, mergedPdfOutput);
            Console.WriteLine("Merged PDF file created at: " + mergedPdfOutput);

            Console.WriteLine("Finished!");
        }

        static void CreateNewPdf(string outputPath, string title)
        {
            using (PdfDocument document = new PdfDocument(new PdfWriter(outputPath)))
            {
                document.SetTitle(title);
                document.Close();
            }
        }

        static void AddTextToNewPdf(string outputPath, string text)
        {
            using (PdfDocument document = new PdfDocument(new PdfWriter(outputPath, new PdfWriter.PdfCreator(null))))
            {
                Document pdfDoc = new Document(document);
                pdfDoc.Add(new Paragraph(text));
                pdfDoc.Close();
            }
        }

        static void AddShapeToNewPdf(string outputPath, string shapeType, float x, float y, float width, float height, Color color)
        {
            using (PdfDocument document = new PdfDocument(new PdfWriter(outputPath, new PdfWriter.PdfCreator(null))))
            {
                Document pdfDoc = new Document(document);
                IShape shape;

                if (shapeType == "Rectangle")
                {
                    shape = new Rectangle(x, y, width, height).SetFillColor(color);
                }
                else if (shapeType == "Line")
                {
                    Line line = new Line(x, y, x + width, y + height).SetLineColor(color).SetLineWidth(1.5f);
                    shape = line;
                }
                else
                {
                    throw new ArgumentException("Invalid shape type: " + shapeType);
                }

                pdfDoc.Add(shape);
                pdfDoc.Close();
            }
        }

        static void MergePdfFiles(string outputPath, params string[] inputFiles)
        {
            using (MemoryStream mergedPdfStream = new MemoryStream())
            {
                PdfMerger merger = new PdfMerger();
                merger.MergePdfFiles(inputFiles, mergedPdfStream);

                using (FileStream outputFile = new FileStream(outputPath, FileMode.Create))
                {
                    mergedPdfStream.WriteTo(outputFile);
                }
            }
        }
    }
}
```

