using iText.Kernel;
using iText.Kernel.Pdf;
using iText.Layout;
using iText.Layout.Element;
using iText.Layout.Properties;

namespace PdfPigDemo
{
    public class PdfCreator
    {
        public PdfDocument CreatePdfDocument(string outputFilePath)
        {
            using var writer = new PdfWriter(outputFilePath);
            using var document = new PdfDocument(writer);

            var builder = new Document(document);
            builder.SetFontSize(12);
            builder.Add(new Paragraph("Hello, iText 7!"));
            builder.Add(new Paragraph("This is the first line of text."));
            builder.Add(new Paragraph("This is the second line of text."));

            // Register a standard font (e.g., Times New Roman)
            var font = PdfFontFactory.CreateFont("Times New Roman", BaseFont.CP1252);

            // Create a new page
            var page = document.AddNewPage();
            var paragraph = new Paragraph("This is the third line of text.", font);
            paragraph.SetTextAlignment(TextAlignment.CENTER);

            // Write text at a different position on the page
            paragraph.SetVerticalAlignment(VerticalAlignment.MIDDLE);
            paragraph.SetFixedPosition(new Point(50, 300), 0);
            builder.Add(paragraph);

            builder.Close();

            return document;
        }
    }
}
```

