using iText.Layout;
using iText.Layout.Element;
using iText.Styles;
using iText.Kernel.Geom;
using iText.Kernel.Colors;
using iText.Kernel.Pdf.Advanced;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace PdfPigDemo
{
    public class PdfMerger
    {
        public byte[] MergePdfFiles(string baseFilePath, params string[] filesToMerge)
        {
            using (MemoryStream ms = new MemoryStream())
            {
                using (PdfDocument baseDocument = new PdfDocument(new File(baseFilePath)))
                {
                    foreach (string filePath in filesToMerge)
                    {
                        using (PdfDocument documentToMerge = new PdfDocument(new File(filePath)))
                        {
                            int numberOfPagesToAdd = documentToMerge.GetNumberOfPages();

                            PdfDocument catalog = baseDocument.GetCatalog();
                            PdfObject pageTree = catalog.GetKids();

                            for (int i = 1; i <= numberOfPagesToAdd; i++)
                            {
                                PdfPage page = documentToMerge.GetPage(i);
                                PdfFormXObject pageObject = new PdfFormXObject();
                                pageObject.SetSize(page.MediaBox.GetWidth(), page.MediaBox.GetHeight());
                                pageObject.SetDirectContext(new Canvas(pageObject.CreateContextToPaint(baseDocument.AddNewPage(MediaBox.CreateA4()))));
                                pageObject.DirectContext.Add(pageObject);
                                pageTree.Add(new PdfObject(new PdfName("/Kids"), new PdfArray(new PdfObject[] { pageObject.DirectContext.GetIndirectObject() })));
                            }
                        }
                    }

                    baseDocument.Save(ms);
                    ms.Position = 0;
                    return ms.ToArray();
                }
            }
        }

        static void Main(string[] args)
        {
            string baseFilePath = "base.pdf";
            string[] filesToMerge = { "file1.pdf", "file2.pdf" };
            byte[] mergedPdf = new PdfMerger().MergePdfFiles(baseFilePath, filesToMerge);
            File.WriteAllBytes("merged.pdf", mergedPdf);
        }
    }
}
