    public class PdfTextExtractor
    {
        public Dictionary<int, string> ExtractTextByPage(string outputPath)
        {
            var extractedTexts = new Dictionary<int, string>();

            using (PdfDocument document = new PdfDocument(new PdfFile("C:/Users/Kris/test.pdf")))
            {
                for (int pageIndex = 0; pageIndex < document.PageCount; pageIndex++)
                {
                    using (PdfPage page = document[pageIndex])
                    {
                        if (page == null) continue;

                        IContentStream contentStream = page.GetContentStream();

                        using (ContentReader reader = new ContentReader(contentStream))
                        {
                            TextExtractor textExtractor = new TextExtractor(reader, TextExtractor.TextRenderingMode.Simple, 12, TextExtractor.TextAlignment.LEFT);
                            string text = textExtractor.ExtractText();
                            extractedTexts.Add(pageIndex + 1, text);
