    public class PdfWordExtractor
    {
        public Dictionary<int, List<string>> GetWordsForPage(string outputPath)
        {
            var wordsPerPage = new Dictionary<int, List<string>>();

            using (PdfDocument document = new PdfDocument(new PdfFile("C:/Users/Kris/test.pdf")))
