Code: using System;
using System.Collections.Generic;
using System.Linq;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;
using UglyToad.PdfPig.DocumentLayoutAnalysis.TextExtractor;
using UglyToad.PdfPig.DocumentLayoutAnalysis.TextExtractor.TextLines;
using UglyToad.PdfPig.DocumentLayoutAnalysis.TextExtractor.TextLines.Model;
using UglyToad.PdfPig.DocumentLayoutAnalysis.TextExtractor.TextLines.TextLineSegments;

namespace PdfPigExample
{
    public class PdfLayoutAnalyzer
    {
        public Dictionary<int, List<TextBlock>> GetTextBlocksForPage(string outputPath)
        {
            var textBlocksPerPage = new Dictionary<int, List<TextBlock>>();

            using (PdfDocument document = new PdfDocument(new PdfFile("C:/Users/Kris/test.pdf")))
            {
                for (int pageIndex = 0; pageIndex < document.PageCount; pageIndex++)
                {
                    using (PdfPage page = document[pageIndex])
                    {
                        if (page == null) continue;

                        IContentStream contentStream = page.GetContentStream();
                        TextExtractor textExtractor = new TextExtractor(contentStream, TextExtractor.TextRenderingMode.Simple, 12, TextExtractor.TextAlignment.LEFT);
                        TextLineSegmentation segmentation = new TextLineSegmentation(textExtractor);

                        List<TextBlock> textBlocks = new List<TextBlock>();

                        foreach (TextLine line in segmentation.ExtractTextLines())
                        {
                            TextBlock textBlock = new TextBlock();
                            textBlock.Text = line.Text;

                            int x1 = line.BoundingBox.Left;
                            int y1 = line.BoundingBox.Top;
                            int x2 = line.BoundingBox.Right;
                            int y2 = line.BoundingBox.Bottom;

                            textBlock.Bounds = new Rectangle(x1, y1, x2 - x1, y2 - y1);
                            textBlocks.Add(textBlock);
                        }

                        textBlocksPerPage.Add(pageIndex + 1, textBlocks);
                    }
                }
            }

            if (!string.IsNullOrEmpty(outputPath))
            {
                using (PdfDocument outputDocument = new PdfDocument())
                {
                    // TODO: Write text blocks per page to the new PDF file.
                    outputDocument.Save(outputPath);
                    outputDocument.Close();
                }
            }

            return textBlocksPerPage;
        }
    }

    public class TextBlock
    {
        public string Text { get; set; }
        public Rectangle Bounds { get; set; }
    }
}
