        public void DrawShapesOnPage(int pageNumber, string outputPath)
        {
            using (PdfDocument document = new PdfDocument(new PdfWriter(outputPath)))
            {
                Document pdfDoc = new Document(document);

                using (PdfPage page = document.AddNewPage())
                {
                    // Set the background color for the page
