Code: using System;
using System.Collections.Generic;
using iText.Kernel.Geom;
using iText.Kernel.Pdf;
using iText.Layout;
using iText.Layout.Element;
using iText.Layout.Properties;
using iText.StyledXmlParser.Parser.Node;

namespace PdfPigExample
{
    public class PdfExtractor
    {
        public List<ImageData> GetImagesFromPage(int pageNumber, string inputPath)
        {
            List<ImageData> images = new List<ImageData>();

            using (PdfDocument document = new PdfDocument(new PdfReader(inputPath)))
            {
                using (PdfPage page = document.GetPage(pageNumber))
                {
                    IList<IElement> elements = page.CreateRenderer().GetDirectChildElements();

                    foreach (IElement element in elements)
                    {
                        if (element is Image image)
                        {
                            ImageData imageData = new ImageData();
                            imageData.ImagePath = image.GetAbsolutePath(page.MediaBox);
                            imageData.ImageWidth = image.GetWidth();
                            imageData.ImageHeight = image.GetHeight();
                            images.Add(imageData);
                        }
                    }
                }
            }

            return images;
        }

        public List<string> GetHyperlinksFromPage(int pageNumber, string inputPath)
        {
            List<string> hyperlinks = new List<string>();

            using (PdfDocument document = new PdfDocument(new PdfReader(inputPath)))
            {
                using (PdfPage page = document.GetPage(pageNumber))
                {
                    IList<IElement> elements = page.CreateRenderer().GetDirectChildElements();

                    foreach (IElement element in elements)
                    {
                        if (element is Paragraph paragraph)
                        {
                            List<IProperty> properties = paragraph.GetProperties();

                            foreach (IProperty property in properties)
                            {
                                if (property is LinkProperty linkProperty)
                                {
                                    hyperlinks.Add(linkProperty.GetUrl());
                                }
                            }
                        }
                    }
                }
            }

            return hyperlinks;
        }
    }

    public class ImageData
    {
        public string ImagePath { get; set; }
        public float ImageWidth { get; set; }
        public float ImageHeight { get; set; }
    }
}
