            {
                if (currentDocument != null)
                    mergedDocument.Add(currentDocument);

                using (PdfDocument documentToMerge = new PdfDocument(new PdfReader(inputFile)))
                {
                    currentDocument = documentToMerge;
                }
            }

            mergedDocument.Close();
            currentDocument.Close();

            return mergedPdfOutput.ToArray();
        }
    }
}
