Code: using System;
using System.Collections.Generic;
using System.Linq;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;
using UglyToad.PdfPig.DocumentLayoutAnalysis.TextExtractor;
using UglyToad.PdfPig.DocumentLayoutAnalysis.TextAnalysis;
using UglyToad.PdfPig.DocumentLayoutAnalysis.TextAnalysis.Model;
using UglyToad.PdfPig.DocumentLayoutAnalysis.TextAnalysis.Model.Entities;
using UglyToad.PdfPig.DocumentLayoutAnalysis.TextAnalysis.Model.Entities.Segments;
using UglyToad.PdfPig.DocumentLayoutAnalysis.TextAnalysis.Model.Entities.Regions;

namespace PdfPigDemo
{
    public class PdfAnalyzer
    {
        public Dictionary<int, List<TextBlock>> AnalyzePageText(string filePath, int pageNumber)
        {
            using var document = ReadDocument(filePath);
            using var page = document.GetPage(pageNumber);
            var textBlockList = new List<TextBlock>();

            if (page == null)
                throw new ArgumentException("Invalid page number.");

            using (var textAnalyzer = new TextAnalyzer(page))
            {
                using (var layoutAnalyzer = textAnalyzer.CreateLayoutAnalyzer())
                {
                    var regions = layoutAnalyzer.AnalyzeLayout();
                    var segments = layoutAnalyzer.AnalyzeTextSegments();

                    foreach (var segment in segments)
                    {
                        var textBlock = new TextBlock(segment.Text, segment.BoundingBox);
                        textBlockList.Add(textBlock);
                    }

                    textBlockList = textBlockList.OrderBy(tb => tb.BoundingBox.Top).ToList();
                }
            }

            return new Dictionary<int, List<TextBlock>> { { pageNumber, textBlockList } };
        }

        private PdfDocument ReadDocument(string filePath)
        {
            using (var document = new PdfDocument(filePath))
            {
                return document;
            }
        }
    }
}
