using iText.Kernel.Colors;
using iText.Kernel.Pdf;
using iText.Layout;
using iText.Layout.Element;
using iText.Layout.Properties;

namespace PdfPigDemo
{
    public class PdfShapeCreator
    {
        public PdfDocument CreatePdfDocumentWithShapes(string outputFilePath)
        {
            using var writer = new PdfWriter(outputFilePath);
            using var document = new PdfDocument(writer);
            using var builder = new Document(document);

            // Create a new page
            var page = document.AddNewPage();

            // Draw a line
            using var line = new Line(new Point(50, 100), new Point(150, 100), new Color(ColorConstants.RED), 2);
            using var lineElement = new DrawElement(line);

            builder.Add(lineElement);

            // Draw a rectangle
            using var rectangle = new Rectangle(new Point(50, 150), new Size(50, 50), new Color(ColorConstants.BLUE), 2);
            using var rectangleElement = new DrawElement(rectangle);

            builder.Add(rectangleElement);

            builder.Close();

            return document;
        }
    }
}
