using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace PdfPigDemo
{
    public class PdfPig
    {
        public string ReadPdfMetadata(string filePath)
        {
            using (PdfDocument document = new PdfDocument(new FileStream(filePath, FileMode.Open, FileAccess.Read)))
            {
                string metadata = "";
                PdfDictionary metadataDict = document.GetCatalog().Get(PdfName.INFO);
                if (metadataDict != null)
                {
                    PdfDictionary titleDict = metadataDict.GetAsDict(PdfName.TITLE);
                    if (titleDict != null) metadata += "Title: " + titleDict.GetAsString().ToString();

                    PdfDictionary authorDict = metadataDict.GetAsDict(PdfName.AUTHOR);
                    if (authorDict != null) metadata += "Author: " + authorDict.GetAsString().ToString();

                    PdfDictionary creationDateDict = metadataDict.GetAsDict(PdfName.CREATION_DATE);
                    if (creationDateDict != null) metadata += "Created: " + creationDateDict.GetAsString().ToString();

                    PdfDictionary modificationDateDict = metadataDict.GetAsDict(PdfName.MOD_DATE);
                    if (modificationDateDict != null) metadata += "Modified: " + modificationDateDict.GetAsString().ToString();

                    PdfDictionary producerDict = metadataDict.GetAsDict(PdfName.PRODUCER);
                    if (producerDict != null) metadata += "Produced by: " + producerDict.GetAsString().ToString();
                }
                return metadata;
            }
        }

        public string ExtractTextFromPdf(string filePath)
        {
            using (PdfDocument document = new PdfDocument(new FileStream(filePath, FileMode.Open, FileAccess.Read)))
            {
                using (PdfReader reader = new PdfReader(document))
                {
                    StringBuilder text = new StringBuilder();
                    for (int i = 1; i <= reader.NumberOfPages; i++)
                    {
                        PdfString pageText = reader.GetTextContent(i);
                        text.Append(pageText.ToString());
                    }
                    return text.ToString();
                }
            }
        }

        public List<string> ExtractWordsFromPdf(string filePath)
        {
            using (PdfDocument document = new PdfDocument(new FileStream(filePath, FileMode.Open, FileAccess.Read)))
            {
                using (PdfReader reader = new PdfReader(document))
                {
                    List<string> words = new List<string>();
                    IList<TextElement> textElements = null;
                    for (int i = 1; i <= reader.NumberOfPages; i++)
                    {
                        textElements = ParserUtil.ParseToList(reader.GetPageNth(i), new Device Independence Parser(), new LayoutContext(document));
                        foreach (TextElement element in textElements)
                        {
                            if (element is Text textElement)
                            {
                                words.Add(textElement.GetText().ToString());
                            }
                        }
                    }
                    return words;
                }
            }
        }

        public void AnalyzeLayout(string filePath)
        {
            using (PdfDocument document = new PdfDocument(new FileStream(filePath, FileMode.Open, FileAccess.Read)))
            {
                PdfPage page = document.GetFirstPage();
                PdfFormXObject contentStream = page.CreateContentStream();
                IList<IElement> elements = LayoutFactory.CreateRootNode().Traverse(LayoutFactory.GetParser(new FileStream(filePath), null).Parse(page.MediaBox));
                for (int i = 0; i < elements.Count; i++)
                {
                    if (elements[i] is Text textElement)
                    {
                        Rectangle boundingBox = textelement.GetTextElement().GetBoundingBox();
                        Console.WriteLine("Text: " + textelement.GetText().ToString() + ", Bounding Box: (" + boundingBox.GetLeft().ToString() + ", " + boundingBox.GetTop().ToString() + "), (" + boundingBox.GetWidth().ToString() + ", " + boundingBox.GetHeight().ToString() + ")");
                    }
                }
                contentStream.Close();
            }
        }

        public void CreateNewPdfWithTextAndShapes(string outputPath)
        {
            using (PdfDocument document = new PdfDocument(new FileStream(outputPath, FileMode.Create, FileAccess.Write)))
            {
                document.AddNewPage();

                PdfFormXObject contentStream = document.GetLastPage().CreateContentStream();

                Paragraph title = new Paragraph("Title")
                    .SetTextColor(Color.WHITE)
                    .SetFontSize(12f)
                    .SetFont(FontFactory.CreateFont(FontProgram.DEFAULT, PdfName.HELVET));

                Paragraph text = new Paragraph("Text")
                    .SetTextColor(Color.WHITE)
                    .SetFontSize(10f)
                    .SetFont(FontFactory.CreateFont(FontProgram.DEFAULT, PdfName.HELVET));

                Rectangle rectangle = new Rectangle(50, 600, 100, 100)
                    .SetFillColor(Color.RED)
                    .SetStrokeColor(Color.BLACK)
                    .SetLineWidth(2f);

                contentStream.BeginText();
                contentStream.MoveTextPosition(new Point(document.GetLastPage().Width / 2, document.GetLastPage().Height / 4));
                contentStream.SetFontSize(12f);
                contentStream.SetTextColor(Color.WHITE);
                contentStream.SetTextFont(FontFactory.CreateFont(FontProgram.DEFAULT, PdfName.HELVET));
                contentStream.Add(title);
                contentStream.MoveTextPosition(new Point(document.GetLastPage().Width / 2, document.GetLastPage().Height / 4 - title.GetHeight()));
                contentStream.SetTextColor(Color.WHITE);
                contentStream.SetTextFont(FontFactory.CreateFont(FontProgram.DEFAULT, PdfName.HELVET));
                contentStream.Add(text);

                contentStream.MovePosition(0, new Point(document.GetLastPage().Width / 2 + title.GetTextRectangle().GetLeft() + text.GetTextRectangle().GetLeft()));
                contentStream.Add(rectangle);
                contentStream.Close();
                document.Save();
            }
        }

        public void MergePdfs(string basePath, string outputPath, params string[] filesToMerge)
        {
            using (PdfDocument baseDocument = new PdfDocument(new FileStream(basePath, FileMode.Open, FileAccess.ReadWrite)))
            {
                foreach (string fileToMerge in filesToMerge)
                {
                    using (PdfDocument documentToMerge = new PdfDocument(new FileStream(fileToMerge, FileMode.Open, FileAccess.ReadWrite)))
                    {
                        int numberOfPagesToAdd = documentToMerge.NumberOfPages;
                        PdfDocument catalog = baseDocument.GetCatalog();
                        PdfObject pageTree = catalog.GetKids();

                        for (int i = 1; i <= numberOfPagesToAdd; i++)
                        {
                            PdfPage page = documentToMerge.GetPageNth(i);
                            PdfFormXObject pageObject = new PdfFormXObject();
                            pageObject.SetSize(page.MediaBox.Width, page.MediaBox.Height);
                            pageObject.SetDirectContext(new Canvas(baseDocument.AddNewPage(page.MediaBox).CreateContentStream()));
                            pageTree.Add(new PdfObject(new PdfName("/Kids"), new PdfArray(pageObject.GetIndirectObject().GetIndirectObject().GetIndirectObject().GetIndirectReference().GetObjectReference().GetObjectId().ToString())));
                        }
                    }
                }

                baseDocument.Save();
                using (PdfDocument mergedDocument = new PdfDocument(new FileStream(outputPath, FileMode.Create, FileAccess.Write)))
                {
                    mergedDocument.Add(baseDocument);
                    for (int i = 1; i < filesToMerge.Length; i++)
                    {
                        using (PdfDocument documentToMerge = new PdfDocument(new FileStream(filesToMerge[i], FileMode.Open, FileAccess.ReadWrite)))
                        {
                            mergedDocument.Add(documentToMerge.GetFirstPage());
                        }
                    }

                    mergedDocument.Save();
                }
            }
        }

        static void Main(string[] args)
        {
            Console.WriteLine("Metadata:");
            string metadataPath = "C:\\Users\\Kris\\test.pdf";
            PdfPig pig = new PdfPig();
            Console.WriteLine(pig.ReadPdfMetadata(metadataPath));

            Console.WriteLine("Extract Text:");
            string textPath = "C:\\Users\\Kris\\test.pdf";
            Console.WriteLine(new String(Encoding.UTF8.GetBytes(pig.ExtractTextFromPdf(textPath))))), Encoding.UTF8);

            Console.WriteLine("Extract Words:");
            string wordsPath = "C:\\Users\\Kris\\test.pdf";
            List<string> words = pig.ExtractWordsFromPdf(wordsPath);
            foreach (string word in words)
            {
                Console.WriteLine(word);
            }

            Console.WriteLine("Layout Analysis:");
            string layoutPath = "C:\\Users\\Kris\\test.pdf";
            pig.AnalyzeLayout(layoutPath);

            Console.WriteLine("Create new PDF:");
            string newPdfPath = "C:\\Users\\Kris\\new_test.pdf";
            pig.CreateNewPdfWithTextAndShapes(newPdfPath);

            Console.WriteLine("Merge PDFs:");
            string basePath = "C:\\Users\\Kris\\base.pdf";
            string outputPath = "C:\\Users\\Kris\\merged.pdf";
            string[] filesToMerge = { "C:\\Users\\Kris\\file1.pdf", "C:\\Users\\Kris\\file2.pdf" };
            pig.MergePdfs(basePath, outputPath, filesToMerge);
        }
    }
}
