            // Analyze layout
            Console.WriteLine("Analyzing layout...");
            PdfLayoutAnalysis layoutAnalysis = new PdfLayoutAnalysis();
            layoutAnalysis.CreatePdfWithAdvancedTextAnalysis(inputFilePath);
            layoutAnalysis.AnalyzePdf(inputFilePath);

