            PdfMerger pdfMerger = new PdfMerger();
            byte[] mergedPdf = pdfMerger.MergePdfFiles(inputFilePath, @"C:\Users\Kris\input1.pdf", @"C:\Users\Kris\input2.pdf");
            using (FileStream outputFileStream = new FileStream(@"C:\Users\Kris\merged.pdf", FileMode.Create, FileAccess.Write, FileShare.None))
            {
