```csharp
using iText.Kernel.Pdf;
using iText.Layout;
using iText.Layout.Element;
using iText.Layout.Properties;
using System;

public class PdfCreator
{
    public PdfDocument CreateNewPdfDocument(string filePath, string text)
    {
        var pdfDocument = new PdfDocument(new PdfWriter(filePath));
        var document = new Document(pdfDocument);

        // Add a new page
        document.Add(new Paragraph("Page 1"));
        document.Add(new Paragraph(""));

        // Register Standard 14 font
        var font = FontFactory.GetFont("Standard14", BaseColor.BLACK);

        // Write text at different positions
        document.Add(new Paragraph("Text 1")
            .SetFont(font)
            .SetTextAlign(TextAlignment.LEFT)
            .SetVerticalAlignment(VerticalAlignment.TOP)
            .SetPosition(36, 720));

        document.Add(new Paragraph("Text 2")
            .SetFont(font)
            .SetTextAlign(TextAlignment.CENTER)
            .SetVerticalAlignment(VerticalAlignment.MIDDLE)
            .SetPosition(200, 550));

        document.Add(new Paragraph("Text 3")
            .SetFont(font)
            .SetTextAlign(TextAlignment.RIGHT)
            .SetVerticalAlignment(VerticalAlignment.BOTTOM)
            .SetPosition(576, 50));

        document.Close();

        return pdfDocument;
    }
}
```

