        {
            shapeDrawer.DrawShapeOnPage(pdfDocument, i, 50, 50, 100, 100, Color.RED, 2, ShapeType.Rectangle);
            shapeDrawer.DrawShapeOnPage(pdfDocument, i, 160, 160, 50, 50, Color.BLUE, 3, ShapeType.Line);
            shapeDrawer.DrawShapeOnPage(pdfDocument, i, 270, 270, 100, 100, Color.GREEN, 5, ShapeType.LineRectangle);
