    {
        string[] inputFiles = new string[] { @"C:\Users\Kris\test1.pdf", @"C:\Users\Kris\test2.pdf" };
        string outputPath = @"C:\Users\Kris\merged.pdf";

        using (var merger = new PdfMerger())
        {
            byte[] mergedPdfBytes = merger.MergePdfFiles(inputFiles, outputPath);
            Console.WriteLine("Merged PDF file saved to: " + outputPath);
        }
    }
}
