namespace PdfPigExample
{
    public class PdfWordExtractor
    {
        public IDictionary<int, IList<string>> GetWordsForPage(PdfDocument document)
        {
            NearestNeighbourWordExtractor wordExtractor = new NearestNeighbourWordExtractor();
            IDictionary<int, IList<string>> wordsPerPage = new Dictionary<int, IList<string>>();

            for (int pageIndex = 0; pageIndex < document.PageCount; pageIndex++)
            {
                IList<TextItem> textItems = document.Pages[pageIndex].TextItems;
                IList<string> words = new List<string>();

                foreach (TextItem textItem in textItems)
                {
                    foreach (TextElement textElement in textItem.TextElements)
                    {
                        if (textElement is TextWord textWord)
                        {
                            words.Add(textWord.Text);
                        }
                    }
                }

                wordsPerPage[pageIndex + 1] = words;
            }

            return wordsPerPage;
        }
    }
}
