Code: using iText.Kernel.Pdf;
using iText.Layout;
using iText.Layout.Property;
using System.IO;
using System.IO.Compression;

public class PdfMerger
{
    public byte[] MergePdfFiles(params string[] inputFilePaths)
    {
        using (MemoryStream outputStream = new MemoryStream())
        {
            using (PdfDocument mergedPdfDocument = new PdfDocument(outputStream))
            {
                using (Document document = new Document(mergedPdfDocument))
                {
                    foreach (string inputFile in inputFilePaths)
                    {
                        using (PdfReader reader = new PdfReader(inputFile))
                        {
                            for (int page = 1; page <= reader.NumberOfPages; page++)
                            {
                                PdfPage pageToMerge = mergedPdfDocument.AddNewPage();
                                PdfContentByte cb = pageToMerge.CreateContent();
                                Image image = Image.Instance(reader.GetPageSize(page).Rotate());
                                image.SetAbsolutePosition(0, 0);
                                cb.AddImage(image);
                                cb.AddTemplate(reader.GetPageTemplate(page).CreateTransformed(new Matrix(1, 0, 0, -1, 0, pageToMerge.Width)));
                            }
                        }
                    }
                }

                document.Close();
                mergedPdfDocument.Close();
                outputStream.Position = 0;
                return outputStream.ToArray();
            }
        }
    }
}
