Code: using System;
using System.IO;
using iText.Kernel.Pdf;
using iText.Layout;
using iText.Layout.Element;
using iText.Layout.Property;
using iText.IO.Image;

namespace PdfPig
{
    class Program
    {
        static void Main(string[] args)
        {
            string inputFilePath = @"C:\Users\Kris\test.pdf";

            // Read metadata
            Console.WriteLine("Reading metadata...");
            PdfMetadata metadata = new PdfMetadata(inputFilePath);
            Console.WriteLine($"Title: {metadata.GetTitle()}");

            // Extract text and words
            Console.WriteLine("Extracting text...");
            PdfTextExtraction textExtraction = new PdfTextExtraction();
            string extractedText = textExtraction.ExtractText(inputFilePath);
            Console.WriteLine($"Extracted Text: {extractedText}");

            // Analyze layout
            Console.WriteLine("Analyzing layout...");
            PdfLayoutAnalysis layoutAnalysis = new PdfLayoutAnalysis();
            layoutAnalysis.CreatePdfWithAdvancedTextAnalysis(inputFilePath);
            layoutAnalysis.AnalyzePdf(inputFilePath);

            // Create a new PDF with text and shapes
            Console.WriteLine("Creating new PDF with text and shapes...");
            PdfShapeDrawing shapeDrawing = new PdfShapeDrawing();
            shapeDrawing.CreatePdfWithTextAndShapes(@"C:\Users\Kris\output.pdf");

            // Merge PDFs
            Console.WriteLine("Merging PDFs...");
            PdfMerger pdfMerger = new PdfMerger();
            byte[] mergedPdf = pdfMerger.MergePdfFiles(inputFilePath, @"C:\Users\Kris\input1.pdf", @"C:\Users\Kris\input2.pdf");
            using (FileStream outputFileStream = new FileStream(@"C:\Users\Kris\merged.pdf", FileMode.Create, FileAccess.Write, FileShare.None))
            {
                outputFileStream.Write(mergedPdf, 0, mergedPdf.Length);
            }
            Console.WriteLine("Merged PDFs saved to merged.pdf");

            Console.WriteLine("Finished!");
        }
    }
}
