Code: using System;
using System.Collections.Generic;
using UglyToad.PdfPig;

namespace PdfPigExample
{
    public class PdfReader
    {
        public PdfDocument ReadPdfFile(string filePath)
        {
            return PdfDocument.Load(filePath);
        }

        public void ReadDocumentInformation(PdfDocument pdfDocument, out int numberOfPages, out string title, out string producer, out string pdfVersion)
        {
            numberOfPages = pdfDocument.PageCount;
            title = pdfDocument.Info.Title;
            producer = pdfDocument.Info.Producer;
            pdfVersion = pdfDocument.Info.Version;
        }

        public PdfDocument OpenPdfFile(string filePath)
        {
            return PdfDocument.Load(filePath);
        }

        public Dictionary<int, string> ExtractTextByPage(PdfDocument pdfDocument)
        {
            Dictionary<int, string> textByPage = new Dictionary<int, string>();

            for (int i = 0; i < pdfDocument.PageCount; i++)
            {
                PdfPage page = pdfDocument[i];
                string text = ContentOrderTextExtractor.ExtractText(page);
                textByPage.Add(i + 1, text);
            }

            return textByPage;
        }

        static void Main(string[] args)
        {
            string filePath = @"C:\Users\Kris\test.pdf";
            using (PdfReader pdfReader = new PdfReader())
            {
                PdfDocument pdfDocument = pdfReader.OpenPdfFile(filePath);
                pdfReader.ReadDocumentInformation(pdfDocument, out int numberOfPages, out string title, out string producer, out string pdfVersion);
                Console.WriteLine($"Title: {title}");
                Console.WriteLine($"Producer: {producer}");
                Console.WriteLine($"Number of Pages: {numberOfPages}");

                Dictionary<int, string> textByPage = pdfReader.ExtractTextByPage(pdfDocument);

                Console.WriteLine("Extracted text per page:");
                foreach (var pageText in textByPage)
                {
                    Console.WriteLine($"Page {pageText.Key}: {pageText.Value}");
                }
            }
        }
    }
}
