Code: using System;
using System.Collections.Generic;
using System.Linq;
using Tesseract;
using UglyToad.PdfPig;

namespace PdfWordExtractor
{
    public class PdfWordExtractor
    {
        public Dictionary<int, Dictionary<string, int>> ExtractWordsByPage(string filePath)
        {
            using (PdfDocument pdfDocument = PdfDocument.Load(filePath))
            {
                var wordsByPage = new Dictionary<int, Dictionary<string, int>>();

                for (int pageNumber = 0; pageNumber < pdfDocument.PageCount; pageNumber++)
                {
                    wordsByPage[pageNumber + 1] = new Dictionary<string, int>();

                    using (ITesseract engine = new TesseractEngine())
                    {
                        engine.Init(@"C:\path\to\tesseract\tessdata", "eng");

                        PdfPage pdfPage = pdfDocument[pageNumber];
                        using (var img = new PdfImage(pdfPage))
                        {
                            using (var page = engine.CreatePageFromImage(img))
                            {
                                var words = engine.Process(page).GetWords();

                                foreach (var word in words)
                                {
                                    wordsByPage[pageNumber + 1].Add(word.Text, word.Position.Left + word.Position.Top);
                                }
                            }
                        }
                        engine.Dispose();
                    }
                }

                return wordsByPage;
            }
        }
    }
}
