Code: using System;
using System.Collections.Generic;
using System.Linq;
using Tesseract;
using UglyToad.PdfBox;
using UglyToad.PdfBox.Text;

namespace PdfLayoutAnalysis
{
    public class PdfLayoutAnalyzer
    {
        public Dictionary<int, List<TextBlock>> AnalyzeLayout(string filePath)
        {
            using (PdfDocument document = new PdfDocument(new FileInputStream(filePath)))
            {
                var textBlocksByPage = new Dictionary<int, List<TextBlock>>();

                for (int pageNumber = 0; pageNumber < document.NumberOfPages; pageNumber++)
                {
                    textBlocksByPage[pageNumber + 1] = ProcessPage(document, pageNumber);
                }

                return textBlocksByPage;
            }
        }

        private List<TextBlock> ProcessPage(IPdfDocument document, int pageNumber)
        {
            using (ITesseract engine = new TesseractEngine())
            {
                engine.Init(@"C:\path\to\tesseract\tessdata", "eng");

                PDPage pdfPage = document.GetPDPage(pageNumber);
                Rectangle rect = pdfPage.MediaBox;
                using (Image image = new Image(pdfPage))
                {
                    engine.Process(image).PageSegments.AddRange(engine.Process(image).PageSegments);
                    engine.Dispose();
                }

                var textBlocks = engine.GetPageText(pdfPage.MediaBox, rect.Width, rect.Height).SplitByLine();

                var orderedTextBlocks = CalculateReadingOrder(pdfPage, textBlocks);

                return orderedTextBlocks;
            }
        }

        private List<TextBlock> CalculateReadingOrder(PDPage pdfPage, List<TextBlock> textBlocks)
        {
            using (iTextSharp.Text.LayoutFactory layoutFactory = new TextLayoutFactory())
            {
                var paragraphBuilder = layoutFactory.GetParagraphBuilder();

                var readingOrder = new List<TextBlock>();

                foreach (var textBlock in textBlocks)
                {
                    var position = pdfPage.GetTextPosition(textBlock.Text);
                    paragraphBuilder.Add(new TextElement(textBlock.Text, position.X, position.Y));

                    var line = paragraphBuilder.CurrentLine();
                    line.Height = textBlock.Height;

                    if (line.TextElements.Last() is TextElement && line.TextElements.Last().Text == textBlock.Text)
                    {
                        readingOrder.Add(textBlock);
                    }

                    paragraphBuilder.Clear();
                }

                return readingOrder;
            }
        }

        public class TextBlock
        {
            public string Text { get; set; }
            public Rectangle Bounds { get; set; }
            public float Height { get; set; }
        }
    }

class Program
{
