Code: using iText.Kernel.Pdf;
using iText.Layout;
using iText.Layout.Element;
using iText.Layout.Properties;
using System;
using System.Collections.Generic;
using System.IO;

public class PdfExtractor
{
    public Image[] GetImagesFromPage(string filePath, int pageNumber)
    {
        using (var pdfDocument = new PdfDocument(new PdfReader(filePath)))
        {
            using (var page = pdfDocument.GetPage(pageNumber));
            var images = new List<Image>();

            for (int i = 0; i < page.GetNumberOfAnnotations(); i++)
            {
                var annotation = page.GetAnnotation(i);
                if (annotation is ImageAnnotation imgAnnotation)
                {
                    using (var imageStream = new FileStream(Path.Combine(Path.GetDirectoryName(filePath), imgAnnotation.GetSubtype() + "_" + imgAnnotation.GetProperties().Get(Properties.Key.Title).ToString() + ".png"), FileMode.Create))
                    {
                        page.CopyImages(new Image(imageStream, imgAnnotation.GetBBox()), new Rectangle(imgAnnotation.GetBBox().GetLeft(), imgAnnotation.GetBBox().GetTop(), imgAnnotation.GetBBox().GetWidth(), imgAnnotation.GetBBox().GetHeight()), imageStream);
                        imageStream.Flush();
                        imageStream.Close();
                        images.Add(Image.GetImageFromStream(new FileStream(Path.Combine(Path.GetDirectoryName(filePath), imgAnnotation.GetSubtype() + "_" + imgAnnotation.GetProperties().Get(Properties.Key.Title).ToString() + ".png"))));
                        File.Delete(Path.Combine(Path.GetDirectoryName(filePath), imgAnnotation.GetSubtype() + "_" + imgAnnotation.GetProperties().Get(Properties.Key.Title).ToString() + ".png"));
                    }
                }
            }

            pdfDocument.Close();
            return images.ToArray();
        }
    }

    public List<string> GetHyperlinksFromPage(string filePath, int pageNumber)
    {
        using (var pdfDocument = new PdfDocument(new PdfReader(filePath)))
        {
            using (var page = pdfDocument.GetPage(pageNumber))
            {
                var hyperlinks = new List<string>();

                for (int i = 0; i < page.Annotations.Size(); i++)
                {
                    var annotation = page.Annotations.Get(i);
                    if (annotation is Anchor anAnchor)
                    {
                        hyperlinks.Add(anAnchor.GetAction().GetProperty(PdfAction.ACTION_GO_TO).GetProperty(PdfName.DESTINATION).ToString());
                    }
                }

                pdfDocument.Close();
                return hyperlinks;
            }
        }
    }
}
