using iText.Text.Ex;

namespace PdfPigDemo
{
    public class PdfTextExtractor
    {
        public Dictionary<int, List<string>> GetWordsForPage()
        {
            using (var document = new PdfDocument("C:/Users/Kris/test.pdf"))
            {
                var extractedWordsByPage = new Dictionary<int, List<string>>();
                for (int i = 1; i <= document.GetNumberOfPages(); i++)
                {
                    using (var page = document.GetPage(i))
                    {
                        var textExtractor = new ContentOrderTextExtractor(new SimpleFontProvider());
                        var words = textExtractor.ExtractText(page).Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
                        extractedWordsByPage[i] = words.ToList();
                    }
                }

                return extractedWordsByPage;
            }
        }
    }
}
