using iText.Common;
using iText.Common.Text;
using iText.IO.Font;
using iText.Kernel.Colors;
using iText.Kernel.Pdf;
using iText.Layout;
using iText.Text;

namespace PdfPigDemo
{
    public static class PdfShapeCreator
    {
        public static void CreateNewPdfWithShapes(string filePath, int width, int height)
        {
            using (var writer = new PdfWriter(filePath, new PdfWriter.PdfWriterConfiguration()))
            {
                using (var document = new Document(writer))
                {
                    // Create a new document and add a page
                    using (var page = document.AddNewPage(width, height))
                    {
                        // Draw a line
                        using (var line = new LineShape(new Rectangle(50, 50, 100, 100)))
                        {
                            line.SetLineWidth(3);
                            line.SetColor(ColorConstants.RED);
                            line.Draw(page.DirectContent);
                        }

                        // Draw a rectangle
                        using (var rectangle = new RectangleShape(new Rectangle(100, 50, 100, 100)))
                        {
                            rectangle.SetFillColor(ColorConstants.GREEN);
                            rectangle.SetLineWidth(2);
                            rectangle.SetLineColor(ColorConstants.BLUE);
                            rectangle.Draw(page.DirectContent);
                        }
                    }

                    document.Close();
                }
            }
        }
    }
}
