using iText.Common.Collections;
using iText.Common.Io;
using iText.Common.Objects;
using iText.Kernel.Geom;
using iText.Kernel.Pdf;
using iText.Layout;
using iText.Layout.Element;
using iText.Layout.Property;
using iText.Text;
using java.io;
using java.util;

namespace PdfExtractorDemo
{
    public class PdfTextExtractor
    {
        public Image[] GetImagesFromPage(string filePath, int pageNumber)
        {
            using (var reader = new PdfReader(filePath))
            {
                var images = new List<Image>();
                using (var pdfWriter = new PdfWriter("temp.pdf"))
                using (var pdDocument = new PdfDocument(pdfWriter))
                {
                    var imageData = reader.GetImageData(pageNumber);
                    var image = new Image(imageData, new Rectangle(0, 0, imageData.Width, imageData.Height))
                        .SetAlignment(ImageAlignment.MIDDLE)
                        .SetScalePercent(100);

                    var imageElement = new Image(image);
                    var document = new Document(pdDocument);
                    document.Add(imageElement);
                    document.Close();

                    using (var stream = new FileStream("temp.pdf"))
                    using (var reader2 = new PdfReader(stream))
                    {
                        var page = reader2.GetPageNth(pageNumber);
                        var rectangles = page.MediaBox.GetRects();

                        foreach (var rectangle in rectangles)
                        {
                            var image = reader2.GetImageAt(pageNumber, rectangle.GetLeft(), rectangle.GetTop(), rectangle.GetWidth(), rectangle.GetHeight());
                            images.Add(image);
                        }
                    }

                    File.Delete("temp.pdf");
                }

                return images.ToArray();
            }
        }

        public IList<string> GetHyperlinksFromPage(string filePath, int pageNumber)
        {
            using (var reader = new PdfReader(filePath))
            {
                var hyperlinks = new ArrayList();
                using (var pdDocument = new PdfDocument(new PdfWriter("temp.pdf")))
                {
                    using (var copy = new PdfCopy(pdDocument, new FileStream("temp.pdf", FileMode.Create, FileAccess.Write, FileShare.None)))
                    {
                        for (var i = 1; i <= reader.NumberOfPages; i++)
                        {
                            copy.AddPage(reader.GetPageNth(i));
                        }

                        using (var document = new Document(pdDocument))
                        {
                            document.Add(new TextProgram().SetText("Extracting Hyperlinks..."));
                            document.Add(new Paragraph(""));
                            document.Add(new TextProgram().SetText("Page " + pageNumber));
                            document.Add(new Paragraph(""));
                            using (var writer = new PdfWriter(new FileStream("output.txt", FileMode.Create, FileAccess.Write, FileShare.None)))
                            using (var pdfDocument = new PdfDocument(writer))
                            using (var document2 = new Document(pdfDocument))
                            {
                                document2.Add(new TextProgram().SetText("Hyperlinks: "));
                                document2.Add(new Paragraph(""));
                                using (var cb = new DirectObject())
                                {
                                    cb.Put(PdfName.TYPE, new PdfName(PdfName.ANNOTS));
                                    var annotations = new List<PdfAnnotation>();
                                    using (var reader = new PdfReader(filePath))
                                    {
                                        var page = reader.GetPageNth(pageNumber);
                                        var rects = page.MediaBox.GetRects();
                                        for (int i = 0; i < rects.Size(); i++)
                                        {
                                            var rectangle = rects.Get(i);
                                            using (var reader2 = new PdfReader(filePath))
                                            {
                                                var annotation = reader2.GetAnnotationAt(pageNumber, rectangle.GetX(), rectangle.GetY(), rectangle.GetWidth(), rectangle.GetHeight());
                                                if (annotation != null && annotation is PdfAction)
                                                {
                                                    var hyperlink = ((PdfAction)annotation).GetAction(new PdfName("OpenUrl"));
                                                    if (hyperlink != null)
                                                    {
                                                        hyperlinks.Add(hyperlink.GetProperty(PdfName.URI));
                                                        annotations.Add(annotation);
                                                    }
                                                }
                                            }
                                        }
                                        cb.Put(new Dictionary(new DictionaryProperty("/TU", new PdfName("/Annots"))).Put(new DictionaryProperty("/Kids"), annotations.ToPdfArray()));
                                    }
                                    using (var stream = new FileStream("temp.pdf"))
                                    using (var writer2 = new PdfWriter(stream))
                                    using (var doc = new Document(writer2))
                                    {
                                        doc.Add(new TextProgram().SetText("Extracted Hyperlinks:"));
                                        doc.Add(new Paragraph(""));
                                        doc.Add(new TextProgram().SetText(string.Join("\n", (IEnumerable)hyperlinks)));
                                        document2.Add(new PdfImportedPage(copy, pageNumber));
                                        document2.Add(new TextProgram().SetText("\n"));
                                        document2.Add(cb);
                                        document2.Close();
                                    }
                                }
                                document.Add(document2.DirectContent.Add(cb));
                                document.Close();
                                pdDocument.Close();
                            }

                            using (var reader2 = new PdfReader("output.txt"))
                            using (var textStream = new StreamReader(reader2.GetResourceAsStream(1)))
                            {
                                Console.WriteLine(textStream.ReadToEnd());
                            }
                        }
                    }
                }
            }

            return (IList<string>)hyperlinks;
        }
    }
}
