using iText.Layout;
using iText.Layout.Element;
using iText.Layout.Properties;
using iText.Kernel.Pdf;
using iText.Kernel.Utils;
using iText.IO.Source;
using NUnit.Framework;
using System;
using System.IO;

namespace PdfPig
{
    public class Program
    {
        static void Main(string[] args)
        {
            string inputPdfPath = @"C:\Users\Kris\test.pdf";
            string outputMergedPdfPath = @"C:\Users\Kris\output.pdf";

            // Read metadata from the input PDF
            PdfMetadata metadata = PdfTextExtractor.GetMetadata(inputPdfPath);
            Console.WriteLine("PDF Metadata:");
            Console.WriteLine(metadata);

            // Extract text and words from the input PDF
            string text = PdfTextExtractor.ExtractText(inputPdfPath);
            Console.WriteLine("\nText Extracted:");
            Console.WriteLine(text);

            // Analyze layout of the input PDF
            // (This functionality is not demonstrated here, as it depends on specific implementation details)

            // Create a new PDF with text and shapes
            PdfDocument newPdf = new PdfDocument(new PdfWriter(@"C:\Users\Kris\new.pdf"));
            Document newDocument = new Document(newPdf);

            Paragraph paragraph = new Paragraph("Hello, World!");
            paragraph.SetTextAlignments(TextAlignment.CENTER);
            newDocument.Add(paragraph);

            newDocument.Close();
            newPdf.Close();

            // Merge the input PDF with the new PDF
            PdfDocument mergedPdf = PdfMerger.MergePdfFiles(new PdfReader(inputPdfPath), new PdfReader(@"C:\Users\Kris\new.pdf"));

            // Save the merged PDF to a file
            FileInfo fileInfo = new FileInfo(outputMergedPdfPath);
            using (var outputStream = File.Create(outputMergedPdfPath))
            {
                new PdfWriter(outputStream).DirectContent.AddDocument(mergedPdf);
            }

            // Close resources
            mergedPdf.Close();
            File.Delete(@"C:\Users\Kris\new.pdf");

            Console.WriteLine("\nMerged PDF saved to: {0}", outputMergedPdfPath);
        }
    }
}
