```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using Tesseract;
using UglyToad.PdfPig;

namespace PdfPigDemo
{
    public class PdfDocumentAnalyzer
    {
        public Dictionary<int, List<TextBlock>> AnalyzePage(int pageNumber)
        {
            using (var engine = new TesseractEngine(@"path\to\your\tesseract.exe", "eng", false))
            using (var document = new Document("C:\\Users\\Kris\\test.pdf"))
            using (var page = document.Pages[pageNumber - 1])
            {
                engine.SetPageSegMode(PageSegMode.ForceNewDetect); // Set to ForceNewDetect for better results
                engine.SetVariable("tessedit_char_whitelist", " "); // optional, to ignore words with certain characters

                TextBlock previousBlock = null;
                var textBlocks = new List<TextBlock>();

                foreach (var chunk in page.Chunks)
                {
                    if (previousBlock != null && chunk.Top > previousBlock.Bottom) // New text block when there's a gap between two chunks
                    {
                        textBlocks.Add(previousBlock);
                        previousBlock = null;
                    }

                    if (previousBlock == null)
                    {
                        previousBlock = new TextBlock { Top = chunk.Top, Left = chunk.Left, Text = chunk.Text };
                    }
                    else
                    {
                        previousBlock.Text += " " + chunk.Text; // Merge text blocks with no gaps
                    }
                }

                if (previousBlock != null)
                {
                    textBlocks.Add(previousBlock);
                }

                var wordsPerPage = new Dictionary<int, List<string>>();

                foreach (var textBlock in textBlocks)
                {
                    using (var image = page.GetImageGraphs()[0].ToBitmap())
                    {
                        string text = engine.Process(image).Text;
                        string[] words = text.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);

                        if (!wordsPerPage.TryGetValue(pageNumber, out var wordsForPage))
                        {
                            wordsForPage = new List<string>();
                            wordsPerPage[pageNumber] = wordsForPage;
                        }

                        wordsForPage.AddRange(words);
                    }
                }

                return wordsPerPage;
            }
        }
    }
}
```

Replace `path\to\your\tesseract.exe` with the actual path to your `tesseract.exe` file in the Tesseract installation directory.

