using System.Collections.Generic;

namespace YourNamespace
{
    public class PdfExtractor
    {
        public PdfDocument OpenPdfFile(string filePath)
        {
            using (var pdfReader = new PdfReader(filePath))
            {
                using (var pdfWriter = new PdfDocument(new PdfWriter(filePath + "_out.pdf")))
                {
                    for (int i = 1; i <= pdfReader.NumberOfPages; i++)
                    {
                        using (var page = new PdfPage(pdfWriter, pdfReader.GetPageSize(i)))
                        {
                            var textExtractor = new TextExtractor(new SimpleTextExtractionStrategy());
                            var content = textExtractor.ExtractTextFromPage(pdfReader.GetPageN(i));

                            // Extract images and hyperlinks here.
                            List<Image> images = GetImagesFromPage(page);
                            List<Link> hyperlinks = GetHyperlinksFromPage(content, pdfReader.GetPageN(i));
                        }
                    }
                }
            }

            return new PdfDocument(new PdfReader(filePath + "_out.pdf"));
        }

        public List<Image> GetImagesFromPage(PdfPage page)
        {
            using (var imageExtractor = new ImageProcessor(page))
            {
                using (var image = new Image(imageExtractor.CreateImage()))
                {
                    return new List<Image> { image };
                }
            }
        }

        public List<Link> GetHyperlinksFromPage(string content, PdfPage page)
        {
            List<Link> hyperlinks = new List<Link>();

            foreach (var textFragment in new TextPositionTextExtractor().ExtractTexts(page))
            {
                if (textFragment.Text.StartsWith("http://") || textFragment.Text.StartsWith("https://"))
                {
                    hyperlinks.Add(new Link(textFragment.Text, textFragment.Text, new URLAction(textFragment.Text)));
                }
            }

            return hyperlinks;
        }
    }
}
