using System;
using System.IO;
using iText.Kernel.Pdf;
using iText.Layout;
using iText.Layout.Element;
using iText.Layout.Property;
using iText.Kernel.Colors;
using iText.Kernel.Geom;
using iText.Kernel.Pdf.Annotations;
using iText.Kernel.Pdf.Action;
using iText.Kernel.Pdf.Diffs;
using iText.Kernel.Pdf.Security;
using iText.Layout.Property;
using iText.Kernel.Text;
using iText.Layout.Text.Element;
using iText.Kernel.Util;
using iText.Layout.Text.Formatting;

namespace PdfPig
{
    class Program
    {
        static void Main(string[] args)
        {
            string baseFilePath = @"C:\Users\Kris\test.pdf";
            string outputFilePath = @"C:\Users\Kris\output.pdf";
            string metadataFilePath = @"C:\Users\Kris\metadata.txt";

            Console.WriteLine("Reading metadata...");
            using (PdfDocument baseDocument = new PdfDocument(new PdfReader(baseFilePath)))
            {
                using (FileStream metadataFileStream = new FileStream(metadataFilePath, FileMode.Create))
                {
                    baseDocument.Writer.DirectContent.Add(new Paragraph("PDF metadata:").SetTextAlign(TextAlign.CENTER).SetFontSize(12).SetFontColor(ColorConstants.BLACK)).DrawOn(metadataFileStream);
                    baseDocument.Writer.DirectContent.ShowText("Title: " + baseDocument.Info.Title + "\n");
                    baseDocument.Writer.DirectContent.ShowText("Author: " + baseDocument.Info.Author + "\n");
                    baseDocument.Writer.DirectContent.ShowText("Creation date: " + baseDocument.Info.CreationDate.ToString("dd.MM.yyyy") + "\n");
                    baseDocument.Writer.DirectContent.ShowText("Last modified: " + baseDocument.Info.ModDate.ToString("dd.MM.yyyy") + "\n");
                    metadataFileStream.Flush();
                }

                Console.WriteLine("Metadata read.");
            }

            Console.WriteLine("Extracting text and words...");
            using (PdfDocument document = new PdfDocument(new PdfReader(baseFilePath), new PdfWriter(outputFilePath)))
            {
                var textExtractor = new TextExtractor(new SimpleTextExtractionStrategy());
                string content = textExtractor.ExtractTextFromPage(new PdfPage(document.GetFirstPage()));

                Console.WriteLine("Total text: " + content.Length);

                var tokenizer = new TextPositionTextExtractor();
                for (int i = 0; i < content.Length; i++)
                {
                    TextPositionTextFragment fragment = tokenizer.ExtractTextPositionText(content, i, i + 1);
                    Console.WriteLine("Word: " + fragment.Text);
                }

                document.Close();
            }

            Console.WriteLine("Analyzing layout...");
            using (PdfDocument pdfDocument = new PdfDocument(new PdfReader(baseFilePath)))
            {
                for (int i = 1; i <= pdfDocument.NumberOfPages; i++)
                {
                    var page = new PdfPage(pdfDocument, pdfDocument.GetPageSizeOrMediaBox(i));
                    using (var canvas = new Canvas(page))
                    {
                        var text = "Analyzing page " + i + ".";
                        var paragraph = new Paragraph(text)
                            .SetTextAlign(TextAlign.CENTER)
                            .SetFontSize(10)
                            .SetFontColor(ColorConstants.DARK_GRAY);

                        canvas.DrawContent(paragraph);
                    }
                }

                using (MemoryStream ms = new MemoryStream())
                {
                    pdfDocument.Close();
                    pdfDocument.SaveTo(ms);
                    byte[] mergedPdf = PdfMerger.MergePdfFiles(ms.ToArray(), @"C:\Users\Kris\test2.pdf");
                    File.WriteAllBytes(@"C:\Users\Kris\output2.pdf", mergedPdf);
                    Console.WriteLine("Layout analyzed.");
                }

                Console.WriteLine("Workflow completed.");
            }
        }
    }
}
