Code: using System;
using System.Collections.Generic;
using System.IO;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;
using iText.Common;
using iText.Common.Text;
using iText.IO.Font;
using iText.Kernel.Pdf;
using iText.Layout;
using iText.Text;
using iText.Text.Ex;
using iText.Text.Layout;

namespace PdfPigDemo
{
    public class PdfTextExtractor
    {
        public Dictionary<int, List<List<string>>> ExtractTextBlocksByPage()
        {
            using (var document = new PdfDocument("C:/Users/Kris/test.pdf"))
            {
                var extractedTextBlocksByPage = new Dictionary<int, List<List<string>>>();
                for (int i = 1; i <= document.GetNumberOfPages(); i++)
                {
                    using (var page = document.GetPage(i))
                    {
                        var contentStream = new PdfContentStream(page.MediaBox);
                        var textExtractionStrategy = new TextExtractionStrategy();

                        var result = new List<List<string>>();
                        var textParser = new ParagraphTextParser(textExtractionStrategy);
                        textParser.Parse(contentStream);
                        result.Add(textParser.getText());

                        extractedTextBlocksByPage[i] = result;
                    }
                }

                return extractedTextBlocksByPage;
            }
        }

        public List<string> GetTextForBlock(int pageNumber, int blockIndex)
        {
            var textBlocksByPage = ExtractTextBlocksByPage();
            return textBlocksByPage[pageNumber][blockIndex];
        }
    }
}
