Code: using System;
using System.IO;
using iText.Kernel.Pdf;
using iText.Layout;
using iText.Kernel.Pdf.Action;
using iText.Kernel.Pdf.Annotations;
using iText.Kernel.Pdf.Color;
using iText.Kernel.Pdf.Canvas;
using iText.Kernel.Pdf.Diffs;
using iText.Kernel.Pdf.Security;
using iText.Layout.Element;

namespace YourNamespace
{
    public class PdfMerger
    {
        public static byte[] MergePdfFiles(string baseFile, params string[] additionalFiles)
        {
            using (var baseDocument = new PdfDocument(new PdfReader(baseFile), new PdfWriter(baseFile)))
            {
                foreach (var file in additionalFiles)
                {
                    using (var reader = new PdfReader(file))
                    {
                        int numberOfPages = reader.NumberOfPages;

                        for (int pageNumber = 1; pageNumber <= numberOfPages; pageNumber++)
                        {
                            using (var page = new PdfPage(baseDocument, baseDocument.GetPageSizeOrMediaBox(baseDocument.GetNumberOfPages())))
                            {
                                using (var readerCopy = new PdfCopy(page, baseDocument))
                                {
                                    var sourcePage = reader.GetPageN(pageNumber);
                                    var writer = readerCopy.DirectContent;

                                    writer.AddTemplate(sourcePage);
                                }
                            }
                        }
                    }
                }

                using (MemoryStream ms = new MemoryStream())
                {
                    baseDocument.Close();
                    baseDocument.SaveTo(ms);
                    return ms.ToArray();
                }
            }
        }
    }
}
