public class ShapeDrawer
{
    public void DrawLine(PdfPageBuilder pageBuilder, float x1, float y1, float x2, float y2, Color color, float lineWidth)
    {
        pageBuilder.AddLine(x1, y1, x2, y2, lineWidth, color);
