            builder.WriteText("This is a new line.", new PdfPoint(100, 680), "Helvetica", 12);
            builder.WriteText("Another line of text.", new PdfPoint(100, 660), "Helvetica", 12);

            // Save the PDF document
            builder.Save();
        }
    }
}
