```csharp
using System;
using System.Collections.Generic;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;
using UglyToad.PdfPig.WordExtractor;

class DocumentLayoutAnalyzer
{
    public List<TextBlock> GetOrderedTextBlocks(int pageNumber)
    {
        string filePath = @"C:\Users\Kris\test.pdf";
        List<TextBlock> textBlocks = new List<TextBlock>();

        using (PdfDocument document = PdfDocument.Open(filePath))
        {
            if (pageNumber >= 1 && pageNumber <= document.PageCount)
            {
                Page page = document.GetPage(pageNumber);
                NearestNeighbourWordExtractor wordExtractor = new NearestNeighbourWordExtractor(page);
                List<Word> words = wordExtractor.GetWords();

                // Group words into text blocks based on their bounding boxes
                foreach (Word word in words)
                {
                    TextBlock block = textBlocks.Find(b => b.BoundingBox.Intersects(word.BoundingBox));
                    if (block == null)
                    {
                        block = new TextBlock { BoundingBox = word.BoundingBox };
                        textBlocks.Add(block);
                    }
                    block.Words.Add(word.Text);
                }

                // Sort text blocks based on their position in the page
                textBlocks.Sort((a, b) => a.BoundingBox.Top.CompareTo(b.BoundingBox.Top));
                textBlocks.Sort((a, b) => a.BoundingBox.Left.CompareTo(b.BoundingBox.Left));
            }
        }

        return textBlocks;
    }
}

class TextBlock
{
    public Rectangle BoundingBox { get; set; }
    public List<string> Words { get; set; } = new List<string>();
}

