```csharp
using System;
using UglyToad.PdfPig.Writer;
using UglyToad.PdfPig.Writer.Fonts;
using UglyToad.PdfPig.Writer.Content;

class Program
{
    static void Main()
    {
        // Create a new PDF document using PdfDocumentBuilder
        using (PdfDocumentBuilder builder = new PdfDocumentBuilder())
        {
            // Add a new page to the document
            builder.AddPage();

            // Register a Standard 14 font (e.g., Helvetica)
            builder.RegisterStandard14Font(Standard14Font.Helvetica);

            // Get the current page
            PdfPage page = builder.GetCurrentPage();

            // Define the positions for the text
            var positions = new[]
            {
                new (100, 700), // First line
                new (100, 680), // Second line
                new (100, 660), // Third line
                new (100, 640)  // Fourth line
            };

            // Define the text to write
            string[] lines = { "First line of text", "Second line of text", "Third line of text", "Fourth line of text" };

            // Write the text at the specified positions
            for (int i = 0; i < positions.Length; i++)
            {
                page.Content.Text.WriteText(positions[i].X, positions[i].Y, lines[i], new TextOptions
                {
                    FontSize = 12,
                    FontName = Standard14Font.Helvetica
                });
            }

            // Build the PDF document and save it to a file
            string outputPath = "output.pdf";
            builder.Build(outputPath);

            Console.WriteLine($"PDF document created at {outputPath}");
        }
    }
}
```

