### PdfProcessor.cs

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;

public class PdfProcessor
{
    public List<Image> GetImagesFromPage(string pdfPath, int pageNumber)
    {
        List<Image> images = new List<Image>();

        using (PdfDocument document = PdfDocument.Open(pdfPath))
        {
            if (pageNumber < 1 || pageNumber > document.PageCount)
            {
                throw new ArgumentException("Invalid page number.");
            }

            PdfPage page = document.GetPage(pageNumber);

            foreach (var image in page.Images)
            {
                byte[] imageBytes = image.GetImageBytes();
                using (MemoryStream ms = new MemoryStream(imageBytes))
                {
                    Image img = Image.FromStream(ms);
                    images.Add(img);
                }
            }
        }

        return images;
    }

    public List<Uri> GetHyperlinksFromPage(string pdfPath, int pageNumber)
    {
        List<Uri> hyperlinks = new List<Uri>();

        using (PdfDocument document = PdfDocument.Open(pdfPath))
        {
            if (pageNumber < 1 || pageNumber > document.PageCount)
            {
                throw new ArgumentException("Invalid page number.");
            }

            PdfPage page = document.GetPage(pageNumber);

            foreach (var element in page.Elements)
            {
                if (element is Content.Text.TextRenderInfo textRenderInfo)
                {
                    foreach (var link in textRenderInfo.TextLinks)
                    {
                        hyperlinks.Add(link);
                    }
                }
                else if (element is Content.Text.TextRenderInfo textRenderInfo)
                {
                    foreach (var link in textRenderInfo.TextLinks)
                    {
                        hyperlinks.Add(link);
                    }
                }
            }
        }

        return hyperlinks;
    }
}
```

