            "C:\\Users\\Kris\\additional2.pdf"
        };

        PdfMerger merger = new PdfMerger();

        try
        {
            byte[] mergedPdfBytes = merger.MergePdfFiles(filePaths);

            string outputPath = "C:\\Users\\Kris\\merged.pdf";
            File.WriteAllBytes(outputPath, mergedPdfBytes);

            Console.WriteLine($"Merged PDF created at {outputPath}");
