```csharp
using System;
using System.Collections.Generic;
using System.IO;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;
using UglyToad.PdfPig.Writer;

class Program
{
    static void Main(string[] args)
    {
        string pdfPath = @"C:\Users\Kris\test.pdf";
        string outputPath = @"C:\Users\Kris\output.pdf";

        // Read Metadata
        PdfDocument document = PdfDocument.Open(pdfPath);
        Console.WriteLine("Metadata:");
        Console.WriteLine($"Title: {document.Info.Title}");
        Console.WriteLine($"Author: {document.Info.Author}");
        Console.WriteLine($"Creation Date: {document.Info.CreationDate}");
        Console.WriteLine($"Modification Date: {document.Info.ModificationDate}");

        // Extract Text and Words
        Console.WriteLine("\nExtracting Text and Words:");
        foreach (PdfPage page in document.GetPages())
        {
            foreach (var element in page.Elements)
            {
                if (element is Content.Text.TextRenderInfo textRenderInfo)
                {
                    Console.WriteLine($"Text: {textRenderInfo.Text}");
                }
            }
        }

        // Analyze Layout
        Console.WriteLine("\nAnalyzing Layout:");
        foreach (PdfPage page in document.GetPages())
        {
            Console.WriteLine($"Page {page.Number} has {page.Elements.Count} elements.");
        }

        // Create a New PDF
        using (PdfDocumentBuilder builder = new PdfDocumentBuilder())
        {
            using (PdfDocument newDocument = PdfDocument.Open(pdfPath))
            {
                for (int i = 1; i <= newDocument.PageCount; i++)
                {
                    builder.AddPage(newDocument.GetPage(i));
                }
            }

            builder.AddPage(new PdfPageBuilder()
                .WithPageNumber(2)
                .AddText("Hello, UglyToad.PdfPig!", 12, new System.Numerics.Vector2(100, 100))
                .AddShape(new PdfShapeBuilder()
                    .WithShapeType(PdfShapeType.Rectangle)
                    .WithRectangle(new System.Numerics.Vector2(200, 200), new System.Numerics.Vector2(100, 100))
                    .WithStroke(new PdfStroke(PdfColor.Black, 1))
                )
            );

            using (FileStream fs = new FileStream(outputPath, FileMode.Create))
            {
                builder.Build(fs);
            }
        }

        Console.WriteLine($"New PDF created at {outputPath}");

        // Merge PDFs
        List<string> filePaths = new List<string>
        {
            pdfPath,
            outputPath
        };

        using (PdfDocumentBuilder builder = new PdfDocumentBuilder())
        {
            foreach (string filePath in filePaths)
            {
                using (PdfDocument documentToMerge = PdfDocument.Open(filePath))
                {
                    for (int i = 1; i <= documentToMerge.PageCount; i++)
                    {
                        builder.AddPage(documentToMerge.GetPage(i));
                    }
                }
            }

            using (FileStream fs = new FileStream("merged_output.pdf", FileMode.Create))
            {
                builder.Build(fs);
            }
        }

        Console.WriteLine("PDFs merged into merged_output.pdf");
    }
}
```
