using System;
using System.Drawing;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Writer;

public class PdfShapeDrawer
{
    private PdfDocumentBuilder _builder;
    private PdfPageBuilder _pageBuilder;

    public PdfShapeDrawer(string filePath)
    {
        _builder = new PdfDocumentBuilder();
        _builder.AddPage();
        _pageBuilder = _builder.GetPageBuilder(0);
        filePath = "sample.pdf";
        using (PdfDocument document = PdfDocument.Open(filePath))
        {
            for (int i = 0; i < document.PageCount; i++)
            {
                Page page = document.GetPage(i + 1);
                _pageBuilder = _builder.GetPageBuilder(i);
            }
        }
    }

    public void DrawLine(Color color, float lineWidth, PointF point1, PointF point2)
    {
        _pageBuilder.DrawLines(new[]
        {
            new Line(point1, point2)
        },
        color.ToPdfColor(),
        lineWidth);
    }

    public void DrawRectangle(Color color, float lineWidth, PointF point1, PointF point2)
    {
        _pageBuilder.DrawLines(new[]
        {
            new Line(point1, new PointF(point2.X, point1.Y)),
            new Line(new PointF(point2.X, point1.Y), point2),
            new Line(point2, new PointF(point1.X, point2.Y)),
            new Line(new PointF(point1.X, point2.Y), point1)
        },
        color.ToPdfColor(),
        lineWidth);
    }

    public void Save()
    {
        PdfDocument document = _builder.Build();
        document.Save("output.pdf");
    }
}

public static class ColorExtensions
{
    public static UglyToad.PdfPig.Colors.Color ToPdfColor(this Color color)
    {
        return new UglyToad.PdfPig.Colors.Color(color.R / 255f, color.G / 255f, color.B / 255f);
    }
}

class Program
{
    static void Main(string[] args)
    {
        PdfShapeDrawer drawer = new PdfShapeDrawer("sample.pdf");
        drawer.DrawLine(Color.Red, 2, new PointF(50, 750), new PointF(500, 750));
        drawer.DrawRectangle(Color.Blue, 2, new PointF(50, 700), new PointF(500, 500));
        drawer.Save();
    }
}
```
