```csharp
using System;
using System.Collections.Generic;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;
using UglyToad.PdfPig.Images;
using UglyToad.PdfPig.Hyperlinks;

public class PdfExtractor
{
    public static void Main(string[] args)
    {
        string filePath = @"C:\Users\Kris\test.pdf";
        PdfDocument document = PdfDocument.Open(filePath);

        foreach (Page page in document.GetPages())
        {
            List<Image> images = GetImagesFromPage(page);
            List<Hyperlink> hyperlinks = GetHyperlinksFromPage(page);

            Console.WriteLine($"Page {page.Number}:");
            Console.WriteLine("Images:");
            foreach (Image image in images)
            {
                Console.WriteLine($"  - {image}");
            }

            Console.WriteLine("Hyperlinks:");
            foreach (Hyperlink hyperlink in hyperlinks)
            {
                Console.WriteLine($"  - {hyperlink}");
            }
        }
    }

    public static List<Image> GetImagesFromPage(Page page)
    {
        List<Image> images = new List<Image>();

        foreach (PageImage image in page.GetImages())
        {
            images.Add(image);
        }

        return images;
    }

    public static List<Hyperlink> GetHyperlinksFromPage(Page page)
    {
        List<Hyperlink> hyperlinks = new List<Hyperlink>();

        foreach (Link link in page.GetLinks())
        {
            if (link is Hyperlink hyperlink)
            {
                hyperlinks.Add(hyperlink);
            }
        }

        return hyperlinks;
    }
}
```

