using System.Drawing;
using UglyToad.PdfPig.Writer;
using UglyToad.PdfPig.Writer.Content;

class ShapeDrawer
{
    // Method to draw a line on a PDF page
    public void DrawLine(PdfPageBuilder pageBuilder, Point startPoint, Point endPoint, Color color, float lineWidth)
    {
        pageBuilder.StrokePath(startPoint.X, startPoint.Y, endPoint.X, endPoint.Y, lineWidth, color);
    }

    // Method to draw a rectangle on a PDF page
    public void DrawRectangle(PdfPageBuilder pageBuilder, Rectangle rectangle, Color color, float lineWidth)
    {
        pageBuilder.StrokePath(rectangle.Left, rectangle.Top, rectangle.Right, rectangle.Top,
                                rectangle.Right, rectangle.Bottom, rectangle.Left, rectangle.Bottom,
                                rectangle.Left, rectangle.Top, lineWidth, color);
    }
}

class Program
{
    static void Main()
    {
        // Create a new PDF document using PdfDocumentBuilder
        using (PdfDocumentBuilder builder = new PdfDocumentBuilder())
        {
            // Add a new page to the document
            builder.AddPage();

            // Get the current page
            PdfPage page = builder.GetCurrentPage();

            // Create an instance of ShapeDrawer
            ShapeDrawer shapeDrawer = new ShapeDrawer();

            // Define colors and line widths
            Color lineColor = Color.Black;
            float lineWidth = 2.0f;

            // Draw a line on the page
            Point startPoint = new Point(100, 700);
            Point endPoint = new Point(300, 500);
            shapeDrawer.DrawLine(page.GetBuilder(), startPoint, endPoint, lineColor, lineWidth);

            // Define a rectangle
            Rectangle rectangle = new Rectangle(400, 700, 100, 50);

            // Draw a rectangle on the page
            shapeDrawer.DrawRectangle(page.GetBuilder(), rectangle, lineColor, lineWidth);

            // Build the PDF document and save it to a file
            string outputPath = "output.pdf";
            builder.Build(outputPath);

            Console.WriteLine($"PDF document created at {outputPath}");
        }
    }
}
