                .AddText("Hello, UglyToad.PdfPig!", 12, new System.Numerics.Vector2(100, 100))
                .AddShape(new PdfShapeBuilder()
                    .WithShapeType(PdfShapeType.Rectangle)
                    .WithRectangle(new System.Numerics.Vector2(200, 200), new System.Numerics.Vector2(100, 100))
                    .WithStroke(new PdfStroke(PdfColor.Black, 1))
                )
            );

            using (FileStream fs = new FileStream(outputPath, FileMode.Create))
            {
                builder.Build(fs);
            }
        }

        Console.WriteLine($"New PDF created at {outputPath}");

        // Merge PDFs
        List<string> filePaths = new List<string>
        {
            pdfPath,
            outputPath
        };

        using (PdfDocumentBuilder builder = new PdfDocumentBuilder())
        {
            foreach (string filePath in filePaths)
            {
                using (PdfDocument documentToMerge = PdfDocument.Open(filePath))
                {
                    for (int i = 1; i <= documentToMerge.PageCount; i++)
                    {
                        builder.AddPage(documentToMerge.GetPage(i));
                    }
                }
            }

            using (FileStream fs = new FileStream("merged_output.pdf", FileMode.Create))
            {
                builder.Build(fs);
            }
        }

        Console.WriteLine("PDFs merged into merged_output.pdf");
    }
}
