using UglyToad.PdfPig;
using UglyToad.PdfPig.DocumentLayoutAnalysis;

public class AdvancedDocumentLayoutAnalyzer
{
    public void AnalyzeDocument()
    {
        // Open the PDF document
        using (PdfDocument document = PdfDocument.Open(@"C:\Users\Kris\test.pdf"))
        {
            for (int i = 0; i < document.PageCount; i++)
            {
                Page page = document.GetPage(i + 1);

                // Extract words from the page
                List<Word> words = WordExtractor.Extract(page);

                // Detect reading order
                ReadingOrderDetector detector = new ReadingOrderDetector();
                PageSegmentation segmenter = new PageSegmentation();
                TextBlock[] textBlocks = detector.DetectReadingOrder(segmenter.Segment(page, words));

                // Output the text blocks
                foreach (TextBlock block in textBlocks)
                {
                    Console.WriteLine(block.Text);
                }
            }
        }
    }
}

class Program
{
    static void Main(string[] args)
    {
        AdvancedDocumentLayoutAnalyzer analyzer = new AdvancedDocumentLayoutAnalyzer();
        analyzer.AnalyzeDocument();
    }
}
