Code: using System;
using System.IO;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;
using UglyToad.PdfPig.Graphics;
using UglyToad.PdfPig.Images;
using UglyToad.PdfPig.Hyperlinks;
using UglyToad.PdfPig.Writer;

class Program
{
    static void Main(string[] args)
    {
        string filePath = @"C:\Users\Kris\test.pdf";

        // Read metadata
        using (PdfDocument document = PdfDocument.Open(filePath))
        {
            Console.WriteLine($"Document Title: {document.Info.Title}");
            Console.WriteLine($"Document Author: {document.Info.Author}");
            Console.WriteLine($"Document Creation Date: {document.Info.CreationDate}");
            Console.WriteLine($"Document Modification Date: {document.Info.ModificationDate}");
        }

        // Extract text and words
        List<TextFragment> textFragments = ExtractText(filePath);
        foreach (var fragment in textFragments)
        {
            Console.WriteLine($"Text: {fragment.Text}");
            Console.WriteLine($"Page Number: {fragment.PageNumber}");
            Console.WriteLine($"Bounding Box: {fragment.BoundingBox}");
            Console.WriteLine($"Font: {fragment.Font}");
            Console.WriteLine($"FontSize: {fragment.FontSize}");
            Console.WriteLine($"Color: {fragment.Color}");
            Console.WriteLine($"IsBold: {fragment.IsBold}");
            Console.WriteLine($"IsItalic: {fragment.IsItalic}");
            Console.WriteLine();
        }

        // Analyze layout
        List<Page> pages = ExtractLayout(filePath);
        foreach (var page in pages)
        {
            Console.WriteLine($"Page Number: {page.Number}");
            Console.WriteLine($"Page Size: {page.Size}");
            Console.WriteLine($"Page Rotation: {page.Rotation}");
            Console.WriteLine($"Text Content: {page.Text}");
            Console.WriteLine($"Shapes: {page.GetShapes().Count}");
            Console.WriteLine($"Images: {page.GetImages().Count}");
            Console.WriteLine($"Hyperlinks: {page.GetLinks().Count}");
            Console.WriteLine();
        }

        // Create a new PDF with text and shapes
        CreateNewPdf(filePath, "C:\\Users\\Kris\\new.pdf");

        // Merge PDFs
        string[] pdfPaths = { filePath, "C:\\Users\\Kris\\new.pdf" };
        byte[] mergedPdf = MergePdfFiles(pdfPaths);
        File.WriteAllBytes("C:\\Users\\Kris\\merged.pdf", mergedPdf);

        Console.WriteLine("All operations completed successfully.");
    }

    static List<TextFragment> ExtractText(string filePath)
    {
        using (PdfDocument document = PdfDocument.Open(filePath))
        {
            return document.GetPage(0).GetText();
        }
    }

    static List<Page> ExtractLayout(string filePath)
    {
        using (PdfDocument document = PdfDocument.Open(filePath))
        {
            return document.GetPages();
        }
    }

    static void CreateNewPdf(string originalFilePath, string newFilePath)
    {
        using (PdfDocument document = PdfDocument.Open(originalFilePath))
        {
            using (PdfDocument newDocument = PdfDocument.Create())
            {
                foreach (var page in document.GetPages())
                {
                    newDocument.AddPage(page);
                }

                // Add new text and shapes
                PdfPage newPage = newDocument.AddPage();
                newPage.Canvas.DrawString("Hello, PdfPig!", new Font("Arial", 12), new PdfRgbColor(0, 0, 0), new PointF(50, 50));
                newPage.Canvas.DrawCircle(new PdfRgbColor(255, 0, 0), new PointF(150, 150), 50);

                newDocument.Save(newFilePath);
            }
        }
    }

    static byte[] MergePdfFiles(string[] filePaths)
    {
        using (PdfDocument outputDocument = new PdfDocument())
        {
            foreach (string filePath in filePaths)
            {
                if (File.Exists(filePath))
                {
                    using (PdfDocument inputDocument = PdfDocument.Open(filePath))
                    {
                        for (int i = 0; i < inputDocument.PageCount; i++)
                        {
                            PdfPage page = inputDocument.Pages[i];
                            outputDocument.AddPage(page);
                        }
                    }
                }
                else
                {
                    throw new FileNotFoundException($"File not found: {filePath}");
                }
            }

            using (MemoryStream output = new MemoryStream())
            {
                outputDocument.Save(output);
                return output.ToArray();
            }
        }
    }
}
