public class PdfDocumentCreator
{
    public void CreatePdfDocument(string outputPath)
    {
        using (PdfDocumentBuilder builder = new PdfDocumentBuilder())
        {
            PdfPage page = builder.AddPage(new PageSize(8.5 * 72, 11 * 72)); // A4 size

