using System;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;
using UglyToad.PdfPig.Writer;

public class PdfShapeDrawer
{
    public void DrawShapes(string outputPath)
    {
        using (PdfDocumentBuilder builder = new PdfDocumentBuilder())
        {
            PdfPage page = builder.AddPage(new PageSize(8.5 * 72, 11 * 72)); // A4 size

            PdfPageBuilder pageBuilder = new PdfPageBuilder(page);

            pageBuilder.DrawLines(Color.Red, 2, new List<PdfLine>
            {
                new PdfLine(new PdfPoint(1 * 72, 10 * 72), new PdfPoint(3 * 72, 10 * 72)),
                new PdfLine(new PdfPoint(1 * 72, 9 * 72), new PdfPoint(3 * 72, 9 * 72))
            });

            pageBuilder.DrawRectangles(Color.Blue, 2, new List<PdfRectangle>
            {
                new PdfRectangle(1 * 72, 8 * 72, 3 * 72, 1 * 72),
                new PdfRectangle(1 * 72, 7 * 72, 3 * 72, 1 * 72)
            });

            builder.Save(outputPath);
        }
    }
}
```

