Code: using System;
using System.Collections.Generic;
using UglyToad.PdfPig;
using UglyToad.PdfPig.DocumentLayoutAnalysis;

public class AdvancedDocumentLayoutAnalyzer
{
    private readonly string _filePath;

    public AdvancedDocumentLayoutAnalyzer(string filePath)
    {
        _filePath = filePath;
    }

    public List<string> AnalyzePage(int pageNumber)
    {
        using (PdfDocument document = PdfDocument.Open(_filePath))
        {
            Page page = document.GetPage(pageNumber);
            DocumentLayout layout = page.GetLayout();

            List<string> orderedTextBlocks = new List<string>();

            foreach (Block block in layout.GetBlocks())
            {
                string textBlock = block.Text;
                if (!string.IsNullOrWhiteSpace(textBlock))
                {
                    orderedTextBlocks.Add(textBlock);
                }
            }

            return orderedTextBlocks;
        }
    }
}
