Code: using System;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Content;
using UglyToad.PdfPig.Writer;

public class PdfDocumentCreator
{
    public void CreatePdfDocument(string outputPath)
    {
        using (PdfDocumentBuilder builder = new PdfDocumentBuilder())
        {
            PdfPage page = builder.AddPage(new PageSize(8.5 * 72, 11 * 72)); // A4 size

            PdfFont font = builder.RegisterFont(PdfFont.Standard14Font);

            page.Content.WriteText("Hello", font, new PdfRectangle(1 * 72, 10 * 72, 3 * 72, 1 * 72)); // 1st line
            page.Content.WriteText("World", font, new PdfRectangle(1 * 72, 9 * 72, 3 * 72, 1 * 72)); // 2nd line

            builder.Save(outputPath);
        }
    }
}
