public class PdfShapeDrawer
{
    private PdfPageBuilder pageBuilder;

    public PdfShapeDrawer(PdfPage page)
    {
        pageBuilder = page.CreatePageBuilder();
    }

    public void DrawLine(int startX, int startY, int endX, int endY, Color color, float lineWidth)
    {
        using (var lineBuilder = pageBuilder.CreateLineBuilder(color, lineWidth))
        {
            lineBuilder.AddLine(startX, startY, endX, endY);
            pageBuilder.DrawLine(lineBuilder);
        }
    }

    public void DrawRectangle(int x, int y, int width, int height, Color color, float lineWidth)
    {
        using (var rectangleBuilder = pageBuilder.CreateRectangleBuilder(color, lineWidth))
        {
            rectangleBuilder.AddRectangle(x, y, width, height);
            pageBuilder.DrawRectangle(rectangleBuilder);
        }
    }
}
