Code: using System;
using System.Collections.Generic;
using System.IO;
using UglyToad.PdfPig;
using UglyToad.PdfPig.Writer;

public class PdfMerger
{
    public byte[] MergePdfFiles(List<string> filePaths)
    {
        if (filePaths == null || filePaths.Count == 0)
        {
            throw new ArgumentException("File paths cannot be null or empty.");
        }

        using (MemoryStream mergedStream = new MemoryStream())
        {
            using (PdfDocumentBuilder documentBuilder = PdfDocumentBuilder.Create(mergedStream))
            {
                foreach (string filePath in filePaths)
                {
                    using (PdfDocument document = PdfDocument.Open(filePath))
                    {
                        foreach (Page page in document.GetPages())
                        {
                            documentBuilder.AddPage(page);
                        }
                    }
                }
                documentBuilder.Save();
            }

            return mergedStream.ToArray();
        }
    }
}
